export const siteSource: Record<string, Record<string, string>> = {"terminal-portfolio":{"FLOW.md":"# FLOW.md — Interaction Model & User Flow Specification\n\nThis document defines the site's navigation architecture, input modes, and keybinding behavior. It is the authority for how users move through the site. Where it conflicts with DESIGN.md on interaction behavior, this document wins. Visual styling, layout dimensions, and theming remain governed by DESIGN.md and THEMES.md.\n\n---\n\n## 1. Core principle: one state, three interfaces\n\nThe site has exactly three input methods:\n\n1. **Clicking** — tabs, clickable command output, buttons\n2. **Shell commands** — `cd`, `ls`, `cat`, etc.\n3. **Keybindings** — vim editing grammar + tmux prefix bindings\n\nAll three are interfaces to a single shared state. They never operate on parallel systems. `cd ~/projects`, pressing `Ctrl+b 2`, and clicking the \"projects\" tab all produce the identical state transition. Implementation must route all three through the same state mutation functions; do not implement click handlers that bypass the command layer (see §5).\n\n### 1.1 Global state shape\n\n```ts\ninterface AppState {\n  activeWindow: WindowId;            // \"about\" | \"projects\" | \"resume\" | \"contact\" | \"help\"\n  windows: Record<WindowId, WindowState>;\n  mode: \"INSERT\" | \"NORMAL\" | \"COPY\";\n  pendingPrefix: boolean;            // true after Ctrl+b, awaiting next key\n  animating: boolean;                // a click-triggered command is being typed\n}\n\ninterface WindowState {\n  panes: PaneState[];                // length 1 except in projects window\n  activePane: number;\n  layout: PaneLayout;                // binary split tree, see §7.3\n}\n\ninterface PaneState {\n  cwd: string;                       // virtual filesystem path\n  inputBuffer: string;\n  cursorPos: number;\n  commandHistory: string[];\n  historyIndex: number | null;\n  scrollback: OutputLine[];\n  scrollOffset: number;              // 0 = pinned to bottom\n  vimState: VimLineState;            // see §6.4\n  view: \"shell\" | \"editor\";          // editor = a file is open via vim (§8.1)\n  editor?: EditorState;              // open file path, cursor, scroll, search state\n}\n```\n\nEach pane is an independent shell session: its own cwd, history, and scrollback. All panes share the one virtual filesystem.\n\n---\n\n## 2. Virtual filesystem ↔ window mapping\n\nTop-level directories ARE tmux windows. This identity is the load-bearing design decision.\n\n```\n~/\n├── about/\n│   ├── about.md\n│   └── uses.md             ← tools/setup, /uses convention\n├── projects/\n│   ├── <project-slug>/\n│   │   ├── README.md\n│   │   └── src/            ← real source files of the project (see §8)\n│   └── ...\n├── resume/\n│   ├── resume.md\n│   ├── resume.pdf          ← cat prints a summary + download link; clicking downloads\n│   └── experience/\n│       ├── <company-slug>.md   ← one per role: depth the resume doc can't hold\n│       └── ...\n├── contact/\n│   └── contact.md\n└── help/\n    ├── guide.md            ← full novice-friendly site guide\n    ├── commands.md         ← shell command reference\n    └── keybindings.md      ← vim + tmux reference, tiered\n```\n\nThe `help` command (§9) prints the quick inline cheatsheet and ends with a clickable `full guide → cd ~/help`. Window and command serve the same content at two depths.\n\n### 2.1 Synchronization rules\n\n| Action | Effect on `cwd` | Effect on `activeWindow` |\n|---|---|---|\n| `cd ~/projects` (or any path under it) | updates | switches to `projects` |\n| `cd` between subdirs of same window | updates | unchanged |\n| `Ctrl+b 2` / `Ctrl+b n` / `Ctrl+b p` | restores that window's last cwd | switches |\n| Click tab | restores that window's last cwd | switches (via animated command, §5) |\n| `cd ~` or `cd /` | sets cwd to `~` | stays on current window; status bar shows `~` |\n\nWindow switching never resets a window's cwd. If the user was deep in `~/projects/foo/src` and switches to resume and back, they return to `~/projects/foo/src`. The animated command for a tab click into a previously-visited window is therefore `cd <that window's saved cwd>`, not the window root.\n\n**First-entry auto-display.** On a window's first activation in a session (by any method — tab, `cd`, `Ctrl+b`), its shell auto-runs one echoed real command so no one ever arrives at an empty prompt: `cat about.md` (about), `ls` (projects), `cat resume.md` (resume), `cat contact.md` (contact), `cat guide.md` (help). The command appears in scrollback exactly as if typed — consistent with the real-commands-only vocabulary, and another passive teaching beat. Subsequent visits restore existing scrollback untouched.\n\nThe home directory `~` is a valid location belonging to no window. The user can `ls` from `~` to see the five directories. This is the \"lobby\" state and is also the initial state on page load (see §4).\n\n---\n\n## 3. The two audiences and their flows\n\n### 3.1 Novice flow (no terminal experience)\n\n1. **Land.** MOTD prints (fast type-on, ~400ms total): one-line identity (\"Christian — developer\"), one-line instruction: `click a tab above, or type 'help'`. Prompt appears.\n2. **Click a tab.** The command animates into the prompt and executes (§5). Window switches, content renders.\n3. **Read content.** All content is normal scrollable rendered markdown inside the terminal frame. Mouse wheel / trackpad / touch scrolling always works in every mode.\n4. **Clickable output.** Every path the terminal prints is interactive: directory names run `cd <name>`, file names run `cat <name>` (also animated). `ls` output is effectively a menu. Links in content (GitHub, email, PDF download) are real anchors.\n5. **Optional learning.** By watching tab clicks type real commands, the novice can graduate to typing `cd contact` themselves. Nothing requires it.\n\nThe novice can complete every site goal (read about, browse projects, view/download resume, read role-by-role experience, find contact info, get help) using clicks alone.\n\n### 3.2 Power user flow\n\n1. **Land.** Same MOTD. Power users recognize the prompt and start typing.\n2. `ls` → see the five directories → `cd projects && ls` → `cat <project>/README.md`.\n3. `Esc` enters NORMAL mode for vim-grammar line editing (§6). `j`/`k` walk command history.\n4. `Ctrl+b [` enters COPY mode to scroll long output with vim motions (§6.3).\n5. `Ctrl+b n/p/1-4/w` for window movement; in projects, `Ctrl+b %` and `\"` to split panes and browse source side-by-side (§7, §8).\n6. `help` at any point prints the full cheatsheet, commands first, bindings second.\n\n### 3.3 Cohesion guarantees\n\n- Tab bar and tmux status-bar window list show identical labels, order, and numbering (1–5). The tab bar IS the window list, rendered large and clickable at the top; the bottom status bar repeats it tmux-style.\n- Clicking and typing produce identical scrollback. A session driven entirely by mouse looks, in scrollback, like a session typed by hand.\n- No GUI-only or CLI-only destinations. Every piece of content is reachable both ways.\n\n---\n\n## 4. Page load sequence\n\nThe landing is a neofetch-style MOTD printed in the lobby (`~`). This resolves the lobby-vs-content tradeoff: the visitor lands at `~`, but the lobby has substance.\n\n1. Window chrome renders immediately (no spinner): title bar, tab bar, status bar, empty terminal.\n2. A last-login line prints: `last login: <real current date/time> on ttys001`.\n3. The **neofetch block** types on (~600ms total, any input skips):\n   - Left: ASCII logo (Christian's mark / initials block art, theme accent colors).\n   - Right column, `label: value` pairs with labels in accent color: `Host` (full name) · `Role` · `Location` · `Shell: zsh` · `Editor: Neovim, tmux` · `Theme` (live — reflects and updates with active theme) · `Stack` · `Uptime` (seconds since page load at print time) · `Contact` (clickable mailto).\n   - Below: the classic neofetch terminal-palette swatch row, rendered from the active theme's ANSI tokens (doubles as a theme preview).\n4. Hint line: `try: cd about · cd projects · cd resume · help` — each clickable, running that exact command via the §5 animation. Hints are real shell, always: the site never invents vocabulary.\n5. Prompt appears: `visitor@christian:~$`. Prompt format everywhere is `visitor@christian:<cwd>$` with cwd abbreviated (`~/projects/foo`).\n6. State: `cwd = ~`, no active window, INSERT mode, focused prompt.\n\n`neofetch` is a first-class command (§9) that reprints this block on demand with current uptime and theme. The MOTD and the command share one renderer.\n\nDeep links: `/<window>` routes (e.g. `/projects`) load with that window active and the equivalent `cd` already in scrollback, as if the user had typed it; the neofetch MOTD still prints above it. Update the URL on window switch (history.pushState) so back/forward buttons work and map to window switches.\n\n---\n\n## 5. Click-to-command animation (decided: always animate)\n\nEvery click that has a command equivalent animates that command into the active pane's prompt, then executes it. This is the teaching mechanism and it always runs.\n\nSpec:\n\n- **What animates:** tab clicks (`cd <path>`), clickable directory names (`cd <name>`), clickable file names (`cat <name>`).\n- **Speed:** type-on at ~15ms/char, capped at 250ms total regardless of command length (scale per-char speed down for long paths). Then a 60ms beat, then execute. Total perceived latency target: under 350ms.\n- **Skippability:** any keypress or second click during animation completes it instantly (full command appears, executes immediately). Never queue animations; the skip rule prevents pile-ups during rapid tab clicking.\n- **Buffer preservation:** if the user has a partially typed command in the prompt when they click, stash it, run the animated command, then restore the stashed text to the new prompt. Do not destroy user input.\n- **Mode interaction:** clicking while in NORMAL or COPY mode returns to INSERT, then animates.\n- **Reduced motion:** if `prefers-reduced-motion`, print the command instantly (still echoed to scrollback) and execute. The echo is the teaching tool; the animation is garnish.\n\n---\n\n## 6. Vim input modes (decided: full operator + motion + count grammar)\n\nThree modes. The status bar always displays the current one.\n\n### 6.1 INSERT (default)\n\nPlain terminal typing. `Enter` executes, `↑`/`↓` walk history (arrow keys work in INSERT as a familiarity affordance), `Ctrl+c` cancels the current line, `Ctrl+l` clears, `Tab` autocompletes paths and command names. `Esc` → NORMAL.\n\n### 6.2 NORMAL (command-line editing)\n\nOperates on the single-line input buffer, modeled on zsh/readline vi-mode. `j`/`k` walk command history (the line is the unit; there is no vertical text motion). Full grammar:\n\n**Structure:** `[count] [operator] [count] [motion | text-object]` — counts multiply (`2d3w` deletes 6 words).\n\n**Motions:** `h l` `w b e` `W B E` `0 ^ $` `f{c} F{c} t{c} T{c}` `; ,` `|`\n**Operators:** `d` `c` `y` (doubled forms `dd cc yy` act on the whole line)\n**Text objects:** `iw aw iW aW` `i\" a\" i' a'` `i( a( i[ a[ i{ a{` `i< a<`\n**Direct commands:** `x X` `r{c}` `~` `s S` `D C Y` `p P` `i a I A` `u` / `Ctrl+r` (line-local undo stack) `.` (repeat last change)\n**History:** `j k` (and `↑ ↓`)\n**Mode exits:** `i a I A s S c{motion}` → INSERT; `Enter` executes from NORMAL; `Esc` clears pending count/operator.\n\nYank/paste use an internal register only (no clipboard integration; native browser copy still works via selection).\n\nUnrecognized keys in NORMAL: flash the status bar mode indicator briefly. Never beep, never print errors into scrollback for keybinding misses.\n\n### 6.3 COPY (scrollback navigation)\n\nEntered with `Ctrl+b [`, exactly like tmux. A position indicator appears top-right of the pane (`[123/456]` lines, tmux-style).\n\n`j k` line scroll · `Ctrl+d Ctrl+u` half page · `Ctrl+f Ctrl+b` full page · `gg G` top/bottom · `{count}G` go to line · `q` or `Esc` or `Enter` exits and re-pins to bottom.\n\nMouse/touch scrolling works in every mode without entering COPY; COPY exists for keyboard users. New output while scrolled up does not yank the view to the bottom; show a `↓ new output` pill that jumps to bottom on click or on COPY-exit.\n\n### 6.4 Mode-conflict rules (implementation-critical)\n\n- The mode indicator reflects the **active pane**. Shell panes report INSERT/NORMAL/COPY; a pane with an open file (§8.1) reports `EDITOR [RO]`. Switching panes switches the indicator; each pane keeps its own state.\n- `Esc` priority order: cancel pending tmux prefix → exit COPY → NORMAL-mode pending count/operator clear → INSERT→NORMAL transition. Inside the editor, `Esc` only clears pending counts/searches (it never closes the file — that's `:q`, matching real vim).\n- `Ctrl+b` is consumed as tmux prefix in ALL modes and views, including inside the editor, and never reaches vim handling. Tmux window/pane navigation must keep working while a file is open; the open file persists in its pane.\n- While `pendingPrefix` is true, the next keypress is interpreted per §7.2 and the status bar shows a `^B` indicator. Any unbound key cancels the prefix silently.\n- Browser shortcut collisions: preventDefault on `Ctrl+b` and `Ctrl+u/d/f` only when terminal is focused. Never intercept `Ctrl+t`, `Ctrl+w`, `Ctrl+n`, `Cmd+anything`, or F-keys — losing a browser tab to a portfolio site is unforgivable.\n\n---\n\n## 7. Tmux layer\n\n### 7.1 Windows\n\nFive fixed windows: `1:about 2:projects 3:resume 4:contact 5:help`. Users cannot create or kill windows. Numbering is stable and matches the tab bar. (Future window slots — e.g. a writing/blog window — append after 5; never renumber existing windows.)\n\n### 7.2 Prefix bindings (`Ctrl+b`, then:)\n\n| Key | Action | Scope |\n|---|---|---|\n| `n` / `p` | next / previous window | all |\n| `1`–`5` | jump to window | all |\n| `w` | window picker overlay (j/k + Enter, or click) | all |\n| `[` | enter COPY mode | all |\n| `%` | split active pane vertically (side-by-side) | projects only |\n| `\"` | split active pane horizontally (stacked) | projects only |\n| `o` | cycle pane focus | projects |\n| `←↑→↓` or `h j k l` | directional pane focus | projects |\n| `x` | close active pane (confirm in status bar: `y/n`) | projects |\n| `z` | zoom/unzoom active pane | projects |\n| `?` | print binding cheatsheet to scrollback | all |\n\n### 7.3 Panes (decided: windows-only everywhere, full user splits in projects)\n\n- about / resume / contact: exactly one pane, always. `%` or `\"` there shows a status-bar notice: `splits are available in the projects window`. This notice doubles as a feature advertisement.\n- projects: full user-created splits. Binary split tree layout (each split divides the focused pane 50/50; minimum pane size ~20 cols / 6 rows — refuse the split with a status-bar notice below minimum). Cap at 4 panes to protect layout sanity. Draggable pane borders are in-scope; persisting layouts across reloads is not (session-only).\n- Each new pane spawns a fresh shell session with cwd inherited from the pane it split from, empty scrollback, and a short header line stating its cwd.\n- Closing the last extra pane returns to single-pane layout. Window switch preserves the projects pane layout for the session.\n- Active pane: bright border (theme accent); inactive: dim border. Clicking a pane focuses it.\n\n---\n\n## 8. Source code browsing (projects window)\n\nEach project directory contains its real source under `src/`, bundled at build time (curated subset per project — entry points and representative files, defined in `data/projects.ts`; do not ship entire node_modules-scale trees).\n\n- `ls` in a source tree behaves normally; output stays clickable.\n- `cat <file>` renders the file inline in scrollback with syntax highlighting (theme-aware, Tokyo Night / Day token colors per THEMES.md) and line numbers. Quick-glance tool; for real reading, use `vim`.\n- Clicking a source file name runs `vim <file>` (animated, per §5); clicking content files like `about.md` still runs `cat`. Heuristic: code extensions open the editor, prose renders inline.\n- `tree` command available: depth-capped (3) clickable tree of the cwd.\n- Intended power flow: split panes, README or `tree` in one, `vim` a source file in the other.\n- Each project README includes its GitHub link; `open <url>` opens a new browser tab (with a status-bar confirm to avoid popup abuse).\n\n### 8.1 Read-only vim viewer\n\n`vim <file>` (alias `view <file>`) opens the file full-pane, taking over the active pane exactly like vim in a real terminal. Behavior models `vim -M` (modifiable off):\n\n- **Navigation (full multi-line vim):** `h j k l`, `w b e W B E`, `0 ^ $`, `gg G {count}G`, `f F t T ; ,`, `{ }`, `%` (bracket match), `Ctrl+d/u/f/b`, `zz zt zb`, counts on everything.\n- **Search:** `/` and `?` with incremental highlight, `n N`, `*` `#` (word under cursor).\n- **Yank:** `y{motion}`, `yy`, visual mode `v`/`V` for selection + `y` (yank also writes the system clipboard — the one place clipboard integration exists, because copying code snippets from a portfolio is a legitimate want).\n- **Edit attempts:** `i a o x d c p` etc. trigger vim's authentic error in the editor's message line: `E21: Cannot make changes, 'modifiable' is off`. This is the joke and the boundary in one move. `:w` → `E45: 'readonly' option is set`.\n- **Ex commands:** `:q` `:q!` close the file and return the pane to its shell (scrollback intact). `:{n}` jumps to line n. `:help` prints the viewer cheatsheet. Anything else → `E492: Not an editor command`.\n- **Chrome:** vim-style statusline inside the pane: `src/index.ts [RO] · 42:7 · 38%`. Relative line numbers with absolute on cursor line (`set rnu nu` style). Status bar mode segment shows `EDITOR [RO]`.\n- **Tmux interop:** `Ctrl+b` bindings all work while a file is open. A pane keeps its open file when unfocused; window switches preserve it for the session.\n- **Novice affordances:** a dismissible one-line hint on first open (`:q to close · / to search · scroll works too`), mouse/touch scrolling and click-to-place-cursor always active, and a small `✕` close affordance in the pane corner that runs `:q`.\n\n**Implementation directive:** build this on CodeMirror 6 with the vim extension (`@replit/codemirror-vim`) in read-only configuration, not a hand-rolled editor. CM6 supplies vim emulation, syntax trees, search, and theming hooks; restyle it to be visually indistinguishable from the terminal (same font, Tokyo Night tokens, transparent background). Hand-rolling multi-line vim is out of the question given the line-editor grammar (§6.2) is already the defect-risk budget. The shell-line vim grammar and the editor's vim emulation are separate implementations by design; do not attempt to share a state machine between them.\n\n### 8.2 Language intelligence (last step, tiered)\n\nLSP-grade features ship after everything else works (see §12.7 phasing). Tiered by feasibility in a static browser context:\n\n| Tier | Languages | Features | Mechanism |\n|---|---|---|---|\n| 1 (baseline, ships with 8.1) | all bundled files | syntax highlighting, document symbols | CM6 Lezer parsers |\n| 2 | TS / JS / TSX / JSON / CSS / HTML | hover types (`K`), diagnostics, go-to-definition (`gd`) **within the project's bundled files**, document outline | TypeScript language service + vscode CSS/JSON/HTML services in a Web Worker over a virtual FS of the bundled `src/` |\n| 3 (best-effort) | other languages a showcased project uses | hover/diagnostics where a maintained WASM language server exists | `codemirror-languageserver` against a WASM LSP, lazy-loaded per language |\n\nRules: all intelligence runs client-side in workers (no backend, no latency cliffs on nav); workers and grammars lazy-load on first `vim` open of a relevant file, never on page load; `gd` across files opens the target in the same pane's editor with a jumplist (`Ctrl+o` / `Ctrl+i` to go back/forward); if a tier-3 server is unavailable for a language, the editor degrades silently to tier 1 — no error states for missing intelligence. Tier 2 alone covers a TS/Next.js portfolio's own source, which is the highest-value target: visitors reading this site's code, in this site, with working go-to-definition.\n\n---\n\n## 9. Command set\n\nAll commands echo into scrollback whether typed or click-animated.\n\n| Command | Behavior |\n|---|---|\n| `ls [path]` | clickable listing; dirs suffixed `/`, theme-colored |\n| `cd [path]` | per §2.1; no arg → `~`; `cd -` → previous cwd |\n| `cat <file>` | render file inline (markdown rendered, code highlighted) |\n| `vim <file>` / `view <file>` | open read-only vim viewer in active pane (§8.1) |\n| `pwd` | print cwd |\n| `tree [path]` | clickable tree, depth 3 |\n| `clear` | clear active pane scrollback |\n| `help` | quick tiered cheatsheet (commands → vim → tmux), ends with clickable `full guide → cd ~/help` |\n| `neofetch` | reprints the landing block (§4) with live uptime and current theme |\n| `whoami` | one-line bio, link to about |\n| `open <url>` | new tab after status-bar confirm |\n| `history` | numbered history; `!{n}` re-runs |\n| `theme [name]` | per THEMES.md; no arg lists themes |\n| `echo`, `date` | flavor; trivial |\n\nUnknown command: `command not found: <x> — try 'help'`. Typo tolerance: if Levenshtein distance 1 from a known command, append `(did you mean '<y>'?)` as clickable text. **Section-name safety net:** a bare section word (`about`, `projects`, `resume`, `contact`) is not a command; it returns `command not found: about — did you mean 'cd about'?` with the suggestion clickable. This is the designed landing spot for the most predictable novice keystroke, and it teaches the real command in the same breath.\n\n`cd`/`cat`/`ls` against nonexistent paths return authentic errors (`no such file or directory: <path>`).\n\n---\n\n## 10. Status bar & window chrome\n\n### 10.1 Title bar (top, per the landing mockup)\n\n- macOS-style traffic lights, left. Decorative by default; close (red) may trigger the `exit` easter-egg response, minimize/maximize are inert. Never actually navigate away.\n- Centered dynamic title: `visitor@christian: <cwd>` (abbreviated), updating on every cwd change — same source of truth as the prompt.\n- Right side: a `?` button (runs `help` via the §5 animation — it is a command in disguise, not a separate help system) and a **theme dropdown**. Selecting a theme from the dropdown echoes and executes `theme <name>` in the active pane, keeping the GUI control inside the one-state rule. The dropdown and the `theme` command list identical options (including `crt (unlocked)` post-Konami).\n- The tab bar sits directly below the title bar: `1:about 2:projects 3:resume 4:contact 5:help`.\n\n### 10.2 Status bar (bottom, tmux-style)\n\nLeft → right: session name (`visitor@christian`) · window list with active highlight (clickable, mirrors tab bar) · mode indicator (`-- INSERT --` / `-- NORMAL --` / `-- COPY --` / `EDITOR [RO]` / `^B` when prefix pending) · cwd · clock (flavor) · `? help` hint.\n\nThe status bar is also the channel for transient notices (pane-split refusals, close confirms, `open` confirms). Notices replace the cwd segment for 3s, then revert. Never use browser `alert()`.\n\n---\n\n## 11. Mobile / touch\n\nKeybindings do not exist on touch. The clickable layer carries mobile entirely:\n\n- Tab bar remains the primary nav; all output stays clickable.\n- A focused tap on the prompt area raises the soft keyboard for users who want to type commands; otherwise typing is never required.\n- Panes: disable split creation below the `md` breakpoint (status-bar notice if somehow triggered); single-pane only on mobile.\n- MOTD on mobile drops the `type 'help'` half of the instruction in favor of `tap a tab above`.\n- COPY mode is irrelevant on touch; native scrolling covers it.\n\n---\n\n## 12. Implementation directives for Claude Code\n\n1. Route ALL navigation through the command executor. Tab click → animate → execute string `cd <path>` through the same parser a typed command uses. One code path.\n2. Vim grammar as a small state machine: accumulate `{count}{operator}{count}{motion}`, resolve on motion/text-object/timeout(Esc). Unit-test the grammar exhaustively (`d2w`, `2dw`, `c i (`, `3fx;`, `.` repeat, `u` stacks). This is the highest-defect-risk component.\n3. Keep the filesystem as a plain typed tree in `data/` (extend CONTENT.md structures); commands resolve paths against it. No async, no fetching for navigation.\n4. Pane layout as a binary tree; render with CSS grid/flex from the tree. Do not hand-roll absolute positioning.\n5. Keyboard handling in one global listener with explicit mode dispatch, honoring §6.4 priority order. No per-component key handlers fighting each other.\n6. Respect `prefers-reduced-motion` everywhere there is animation (MOTD, click-echo, cursor blink optional).\n7. Phase fit (ROADMAP.md): core windows + commands + INSERT mode land before the vim grammar; the rest layers on in dependency order. Suggested insertion: **4a** line-editor vim grammar + COPY mode · **4b** panes + source browsing + `cat` highlighting · **4c** read-only vim viewer (§8.1, tier-1 intelligence) · **5x (final, after Phase 6 themes if desired)** tier-2/3 language intelligence (§8.2). LSP work is explicitly last: it is the only component with heavy lazy-loaded dependencies and zero impact on core navigation.\n\n---\n\n## 13. Out of scope (v1)\n\n- User-created windows, detachable sessions, `tmux` command emulation beyond bindings\n- **Saving edits, anywhere.** The viewer is permanently read-only (`vim -M` semantics, §8.1); there is no write path to the virtual filesystem\n- Pipes, redirection, globbing, environment variables\n- Persisting pane layouts, open files, or history across reloads\n- In the shell line editor (§6.2): clipboard registers, macros (`q`), marks, visual mode (the §8.1 viewer has visual-mode yank; the command line does not)\n\nEach exclusion is a candidate for a later phase; none blocks the core experience.\n","lib/vim/machine.ts":"/**\n * The NORMAL-mode state machine (FLOW §6.2, §12.2). One entry point,\n * handleKey, accumulating `[count][operator][count][motion|textobject]` and\n * resolving on completion. Pure: (buffer, state, key) → result.\n */\nimport { FIND_KEYS, findChar, motion } from \"./motions\";\nimport { textObjectSpan, type Span } from \"./textObjects\";\nimport type { KeyInput, LineVimState, Operator, VimBuffer, VimResult } from \"./types\";\n\nexport function initialVimState(): LineVimState {\n  return {\n    count1: \"\",\n    operator: null,\n    count2: \"\",\n    pending: null,\n    register: \"\",\n    lastFind: null,\n    lastChange: null,\n    undo: [],\n    redo: [],\n    curKeys: [],\n  };\n}\n\nconst clampNormal = (text: string, pos: number) =>\n  Math.max(0, Math.min(pos, Math.max(0, text.length - 1)));\n\ninterface Ctx {\n  buf: VimBuffer;\n  vim: LineVimState;\n  recording: boolean;\n}\n\nfunction counts(vim: LineVimState): number {\n  const c1 = vim.count1 ? parseInt(vim.count1, 10) : 1;\n  const c2 = vim.count2 ? parseInt(vim.count2, 10) : 1;\n  return c1 * c2;\n}\n\nfunction clearPending(vim: LineVimState): LineVimState {\n  return { ...vim, count1: \"\", count2: \"\", operator: null, pending: null, curKeys: [] };\n}\n\nfunction flash(ctx: Ctx): VimResult {\n  return { buf: ctx.buf, vim: clearPending(ctx.vim), flash: true, handled: true };\n}\n\nfunction moveTo(ctx: Ctx, pos: number): VimResult {\n  return {\n    buf: { text: ctx.buf.text, pos: clampNormal(ctx.buf.text, pos) },\n    vim: clearPending(ctx.vim),\n    handled: true,\n  };\n}\n\n/** Commit a text change: push undo, clear redo, record for `.`. */\nfunction commit(\n  ctx: Ctx,\n  next: VimBuffer,\n  opts: { register?: string; toInsert?: boolean } = {},\n): VimResult {\n  const vim: LineVimState = {\n    ...clearPending(ctx.vim),\n    undo: [...ctx.vim.undo, { ...ctx.buf }],\n    redo: [],\n    register: opts.register !== undefined ? opts.register : ctx.vim.register,\n    lastChange: ctx.recording ? [...ctx.vim.curKeys] : ctx.vim.lastChange,\n  };\n  const pos = opts.toInsert ? next.pos : clampNormal(next.text, next.pos);\n  return {\n    buf: { text: next.text, pos },\n    vim,\n    mode: opts.toInsert ? \"INSERT\" : undefined,\n    handled: true,\n  };\n}\n\nfunction applySpan(ctx: Ctx, op: Operator, span: Span): VimResult {\n  const { text } = ctx.buf;\n  const start = Math.max(0, Math.min(span.start, span.end));\n  const end = Math.min(text.length, Math.max(span.start, span.end));\n  const cut = text.slice(start, end);\n  if (op === \"y\") {\n    return {\n      buf: { text, pos: clampNormal(text, start) },\n      vim: { ...clearPending(ctx.vim), register: cut },\n      handled: true,\n    };\n  }\n  const nextText = text.slice(0, start) + text.slice(end);\n  return commit(ctx, { text: nextText, pos: start }, { register: cut, toInsert: op === \"c\" });\n}\n\nfunction operatorMotionSpan(\n  pos: number,\n  target: number,\n  inclusive: boolean,\n): Span {\n  if (target >= pos) return { start: pos, end: target + (inclusive ? 1 : 0) };\n  return { start: target, end: pos };\n}\n\n/** Replay the recorded keys of the last change (the `.` command). */\nfunction repeatLastChange(ctx: Ctx): VimResult {\n  const keys = ctx.vim.lastChange;\n  if (!keys || keys.length === 0) return flash(ctx);\n  let buf = ctx.buf;\n  let vim: LineVimState = { ...clearPending(ctx.vim) };\n  let mode: \"INSERT\" | undefined;\n  for (const key of keys) {\n    const r = handleKeyInternal(buf, vim, { key }, false);\n    buf = r.buf;\n    vim = r.vim;\n    if (r.mode === \"INSERT\") mode = \"INSERT\";\n  }\n  // The replay must not overwrite the recorded change.\n  vim = { ...vim, lastChange: keys };\n  return { buf, vim, mode, handled: true };\n}\n\nfunction resolvePendingInput(ctx: Ctx, input: KeyInput): VimResult {\n  const { buf, vim } = ctx;\n  const pending = vim.pending!;\n  const key = input.key;\n  if (key === \"Escape\") {\n    return { buf, vim: clearPending(vim), handled: true };\n  }\n  if (key.length !== 1) return flash(ctx);\n\n  if (pending.kind === \"find\") {\n    const n = counts(vim);\n    const found = findChar(buf.text, buf.pos, pending.cmd, key, n);\n    const vimWithFind = { ...vim, lastFind: { cmd: pending.cmd, char: key } };\n    if (!found) return { buf, vim: clearPending(vimWithFind), handled: true, flash: true };\n    if (vim.operator) {\n      return applySpan(\n        { ...ctx, vim: vimWithFind },\n        vim.operator,\n        operatorMotionSpan(buf.pos, found.target, found.inclusive),\n      );\n    }\n    return moveTo({ ...ctx, vim: vimWithFind }, found.target);\n  }\n\n  if (pending.kind === \"replace\") {\n    const n = counts(vim);\n    if (buf.pos + n > buf.text.length) return flash(ctx);\n    const next =\n      buf.text.slice(0, buf.pos) + key.repeat(n) + buf.text.slice(buf.pos + n);\n    return commit(ctx, { text: next, pos: buf.pos + n - 1 });\n  }\n\n  // text object\n  const span = textObjectSpan(buf.text, buf.pos, pending.mode, key, counts(vim));\n  if (!span) return flash(ctx);\n  return applySpan(ctx, vim.operator!, span);\n}\n\nfunction handleKeyInternal(\n  bufIn: VimBuffer,\n  vimIn: LineVimState,\n  input: KeyInput,\n  recording: boolean,\n): VimResult {\n  // Record every key of the command being assembled (counts, ops, args).\n  const vim: LineVimState = { ...vimIn, curKeys: [...vimIn.curKeys, input.key] };\n  const buf = bufIn;\n  const ctx: Ctx = { buf, vim, recording };\n  const key = input.key;\n\n  if (vim.pending) return resolvePendingInput(ctx, input);\n\n  // Ctrl combos first.\n  if (input.ctrl) {\n    if (key === \"r\") {\n      const redo = vim.redo[vim.redo.length - 1];\n      if (!redo) return flash(ctx);\n      return {\n        buf: { ...redo },\n        vim: {\n          ...clearPending(vim),\n          undo: [...vim.undo, { ...buf }],\n          redo: vim.redo.slice(0, -1),\n        },\n        handled: true,\n      };\n    }\n    return { buf, vim: vimIn, handled: false };\n  }\n\n  // Counts. A bare 0 is a motion; 0 after digits extends the count.\n  if (/^[0-9]$/.test(key)) {\n    const slot = vim.operator ? \"count2\" : \"count1\";\n    if (key !== \"0\" || vim[slot] !== \"\") {\n      return { buf, vim: { ...vim, [slot]: vim[slot] + key }, handled: true };\n    }\n  }\n\n  switch (key) {\n    case \"Escape\":\n      return { buf, vim: clearPending(vim), handled: true };\n\n    case \"Enter\":\n      return { buf, vim: clearPending(vim), effect: \"execute\", handled: true };\n\n    case \"j\":\n    case \"ArrowDown\":\n      if (vim.operator) return flash(ctx);\n      return { buf, vim: clearPending(vim), effect: \"history-down\", handled: true };\n    case \"k\":\n    case \"ArrowUp\":\n      if (vim.operator) return flash(ctx);\n      return { buf, vim: clearPending(vim), effect: \"history-up\", handled: true };\n\n    case \"d\":\n    case \"c\":\n    case \"y\": {\n      const op = key as Operator;\n      if (vim.operator === op) {\n        // dd / cc / yy — the whole line.\n        return applySpan(ctx, op, { start: 0, end: buf.text.length });\n      }\n      if (vim.operator) return flash(ctx);\n      return { buf, vim: { ...vim, operator: op }, handled: true };\n    }\n\n    case \"i\":\n    case \"a\":\n      if (vim.operator) {\n        return { buf, vim: { ...vim, pending: { kind: \"textobj\", mode: key } }, handled: true };\n      }\n      if (key === \"i\") {\n        return { buf, vim: clearPending(vim), mode: \"INSERT\", handled: true };\n      }\n      return {\n        buf: { text: buf.text, pos: Math.min(buf.text.length, buf.pos + 1) },\n        vim: clearPending(vim),\n        mode: \"INSERT\",\n        handled: true,\n      };\n\n    case \"I\": {\n      if (vim.operator) return flash(ctx);\n      const m = buf.text.match(/\\S/);\n      return {\n        buf: { text: buf.text, pos: m ? m.index! : 0 },\n        vim: clearPending(vim),\n        mode: \"INSERT\",\n        handled: true,\n      };\n    }\n    case \"A\":\n      if (vim.operator) return flash(ctx);\n      return {\n        buf: { text: buf.text, pos: buf.text.length },\n        vim: clearPending(vim),\n        mode: \"INSERT\",\n        handled: true,\n      };\n\n    case \"x\": {\n      if (vim.operator) return flash(ctx);\n      const n = counts(vim);\n      if (buf.text.length === 0) return flash(ctx);\n      return applySpan(ctx, \"d\", { start: buf.pos, end: buf.pos + n });\n    }\n    case \"X\": {\n      if (vim.operator) return flash(ctx);\n      if (buf.pos === 0) return flash(ctx);\n      const n = counts(vim);\n      return applySpan(ctx, \"d\", { start: Math.max(0, buf.pos - n), end: buf.pos });\n    }\n\n    case \"s\": {\n      if (vim.operator) return flash(ctx);\n      const n = counts(vim);\n      const cut = buf.text.slice(buf.pos, buf.pos + n);\n      const next = buf.text.slice(0, buf.pos) + buf.text.slice(buf.pos + n);\n      return commit(ctx, { text: next, pos: buf.pos }, { register: cut, toInsert: true });\n    }\n    case \"S\":\n      return applySpan(ctx, \"c\", { start: 0, end: buf.text.length });\n\n    case \"D\":\n      if (vim.operator) return flash(ctx);\n      return applySpan(ctx, \"d\", { start: buf.pos, end: buf.text.length });\n    case \"C\":\n      if (vim.operator) return flash(ctx);\n      return applySpan(ctx, \"c\", { start: buf.pos, end: buf.text.length });\n    case \"Y\":\n      if (vim.operator) return flash(ctx);\n      return applySpan(ctx, \"y\", { start: 0, end: buf.text.length });\n\n    case \"r\":\n      if (vim.operator) return flash(ctx);\n      return { buf, vim: { ...vim, pending: { kind: \"replace\" } }, handled: true };\n\n    case \"~\": {\n      if (vim.operator) return flash(ctx);\n      const n = Math.min(counts(vim), buf.text.length - buf.pos);\n      if (n <= 0) return flash(ctx);\n      const seg = buf.text.slice(buf.pos, buf.pos + n);\n      const toggled = [...seg]\n        .map((c) => (c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase()))\n        .join(\"\");\n      const next = buf.text.slice(0, buf.pos) + toggled + buf.text.slice(buf.pos + n);\n      return commit(ctx, { text: next, pos: buf.pos + n });\n    }\n\n    case \"p\":\n    case \"P\": {\n      if (vim.operator) return flash(ctx);\n      if (!vim.register) return flash(ctx);\n      const n = counts(vim);\n      const paste = vim.register.repeat(n);\n      const at = key === \"p\" ? Math.min(buf.pos + 1, buf.text.length) : buf.pos;\n      const next = buf.text.slice(0, at) + paste + buf.text.slice(at);\n      return commit(ctx, { text: next, pos: at + paste.length - 1 });\n    }\n\n    case \"u\": {\n      if (vim.operator) return flash(ctx);\n      const last = vim.undo[vim.undo.length - 1];\n      if (!last) return flash(ctx);\n      return {\n        buf: { ...last },\n        vim: {\n          ...clearPending(vim),\n          undo: vim.undo.slice(0, -1),\n          redo: [...vim.redo, { ...buf }],\n        },\n        handled: true,\n      };\n    }\n\n    case \".\":\n      if (vim.operator) return flash(ctx);\n      return repeatLastChange(ctx);\n  }\n\n  if (FIND_KEYS.has(key)) {\n    return {\n      buf,\n      vim: { ...vim, pending: { kind: \"find\", cmd: key as \"f\" | \"F\" | \"t\" | \"T\" } },\n      handled: true,\n    };\n  }\n\n  if (key === \";\" || key === \",\") {\n    const lf = vim.lastFind;\n    if (!lf) return flash(ctx);\n    let cmd = lf.cmd;\n    if (key === \",\") {\n      cmd = ({ f: \"F\", F: \"f\", t: \"T\", T: \"t\" } as const)[cmd];\n    }\n    const found = findChar(buf.text, buf.pos, cmd, lf.char, counts(vim));\n    if (!found) return flash(ctx);\n    if (vim.operator) {\n      return applySpan(ctx, vim.operator, operatorMotionSpan(buf.pos, found.target, found.inclusive));\n    }\n    return moveTo(ctx, found.target);\n  }\n\n  const m = motion(key, buf.text, buf.pos, counts(vim));\n  if (m === null) return flash(ctx);\n  if (m !== undefined) {\n    if (vim.operator) {\n      // vim quirk: cw/cW on a non-blank acts like ce/cE.\n      if (vim.operator === \"c\" && (key === \"w\" || key === \"W\") && /\\S/.test(buf.text[buf.pos] ?? \"\")) {\n        const e = motion(key === \"w\" ? \"e\" : \"E\", buf.text, buf.pos, counts(vim))!;\n        return applySpan(ctx, \"c\", operatorMotionSpan(buf.pos, e.target, e.inclusive));\n      }\n      return applySpan(ctx, vim.operator, operatorMotionSpan(buf.pos, m.target, m.inclusive));\n    }\n    return moveTo(ctx, m.target);\n  }\n\n  return flash(ctx);\n}\n\nexport function handleKey(buf: VimBuffer, vim: LineVimState, input: KeyInput): VimResult {\n  return handleKeyInternal(buf, vim, input, true);\n}\n","lib/vim/motions.ts":"/**\n * Motions return a raw target index plus inclusivity. Plain movement clamps\n * the target to the line; operators build their span from it. A null result\n * means the motion failed (e.g. `f` found nothing) and the command aborts.\n */\n\nexport interface MotionResult {\n  target: number;\n  /** Inclusive motions extend an operator span one char right. */\n  inclusive: boolean;\n}\n\n/** 0 = whitespace, 1 = word chars, 2 = other (punctuation). */\nfunction charClass(c: string): 0 | 1 | 2 {\n  if (/\\s/.test(c)) return 0;\n  if (/\\w/.test(c)) return 1;\n  return 2;\n}\n\n/** WORD class: whitespace vs not. */\nfunction bigClass(c: string): 0 | 1 {\n  return /\\s/.test(c) ? 0 : 1;\n}\n\ntype Classifier = (c: string) => number;\n\nfunction nextWordStart(text: string, pos: number, cls: Classifier): number {\n  let i = pos;\n  if (i >= text.length) return text.length;\n  const start = cls(text[i]);\n  if (start !== 0) {\n    while (i < text.length && cls(text[i]) === start) i++;\n  }\n  while (i < text.length && cls(text[i]) === 0) i++;\n  return i;\n}\n\nfunction prevWordStart(text: string, pos: number, cls: Classifier): number {\n  let i = pos - 1;\n  while (i >= 0 && cls(text[i]) === 0) i--;\n  if (i < 0) return 0;\n  const c = cls(text[i]);\n  while (i > 0 && cls(text[i - 1]) === c) i--;\n  return i;\n}\n\nfunction wordEnd(text: string, pos: number, cls: Classifier): number {\n  let i = pos + 1;\n  while (i < text.length && cls(text[i]) === 0) i++;\n  if (i >= text.length) return Math.max(0, text.length - 1);\n  const c = cls(text[i]);\n  while (i + 1 < text.length && cls(text[i + 1]) === c) i++;\n  return i;\n}\n\nfunction repeat(n: number, pos: number, step: (p: number) => number): number {\n  let p = pos;\n  for (let i = 0; i < n; i++) p = step(p);\n  return p;\n}\n\nexport function findChar(\n  text: string,\n  pos: number,\n  cmd: \"f\" | \"F\" | \"t\" | \"T\",\n  char: string,\n  count: number,\n): MotionResult | null {\n  if (cmd === \"f\" || cmd === \"t\") {\n    let i = pos;\n    for (let n = 0; n < count; n++) {\n      i = text.indexOf(char, i + 1);\n      if (i < 0) return null;\n    }\n    return { target: cmd === \"t\" ? i - 1 : i, inclusive: true };\n  }\n  let i = pos;\n  for (let n = 0; n < count; n++) {\n    i = text.lastIndexOf(char, i - 1);\n    if (i < 0) return null;\n  }\n  return { target: cmd === \"T\" ? i + 1 : i, inclusive: false };\n}\n\n/** Simple (single-key) motions. Returns null if the key isn't a motion. */\nexport function motion(\n  key: string,\n  text: string,\n  pos: number,\n  count: number,\n): MotionResult | null | undefined {\n  switch (key) {\n    case \"h\":\n      return { target: Math.max(0, pos - count), inclusive: false };\n    case \"l\":\n      return { target: Math.min(text.length, pos + count), inclusive: false };\n    case \"0\":\n      return { target: 0, inclusive: false };\n    case \"^\": {\n      const m = text.match(/\\S/);\n      return { target: m ? m.index! : 0, inclusive: false };\n    }\n    case \"$\":\n      return { target: text.length, inclusive: false };\n    case \"w\":\n      return { target: repeat(count, pos, (p) => nextWordStart(text, p, charClass)), inclusive: false };\n    case \"W\":\n      return { target: repeat(count, pos, (p) => nextWordStart(text, p, bigClass)), inclusive: false };\n    case \"b\":\n      return { target: repeat(count, pos, (p) => prevWordStart(text, p, charClass)), inclusive: false };\n    case \"B\":\n      return { target: repeat(count, pos, (p) => prevWordStart(text, p, bigClass)), inclusive: false };\n    case \"e\":\n      return { target: repeat(count, pos, (p) => wordEnd(text, p, charClass)), inclusive: true };\n    case \"E\":\n      return { target: repeat(count, pos, (p) => wordEnd(text, p, bigClass)), inclusive: true };\n    case \"|\":\n      return { target: Math.min(Math.max(0, count - 1), Math.max(0, text.length - 1)), inclusive: false };\n    default:\n      return undefined;\n  }\n}\n\nexport const MOTION_KEYS = new Set([\"h\", \"l\", \"0\", \"^\", \"$\", \"w\", \"W\", \"b\", \"B\", \"e\", \"E\", \"|\"]);\nexport const FIND_KEYS = new Set([\"f\", \"F\", \"t\", \"T\"]);\n\nexport { charClass, bigClass, nextWordStart, prevWordStart, wordEnd };\n","lib/vim/textObjects.ts":"/**\n * Text objects (FLOW §6.2): iw aw iW aW, quote pairs, bracket pairs.\n * Spans are [start, end). Null = object not found (command aborts).\n * Vim quirks preserved: quote objects search forward on the line; bracket\n * objects require the cursor to be on or inside the pair.\n */\nimport { bigClass, charClass } from \"./motions\";\n\nexport interface Span {\n  start: number;\n  end: number;\n}\n\nconst BRACKETS: Record<string, [string, string]> = {\n  \"(\": [\"(\", \")\"],\n  \")\": [\"(\", \")\"],\n  b: [\"(\", \")\"],\n  \"[\": [\"[\", \"]\"],\n  \"]\": [\"[\", \"]\"],\n  \"{\": [\"{\", \"}\"],\n  \"}\": [\"{\", \"}\"],\n  B: [\"{\", \"}\"],\n  \"<\": [\"<\", \">\"],\n  \">\": [\"<\", \">\"],\n};\n\nconst QUOTES = new Set(['\"', \"'\", \"`\"]);\n\nfunction wordObject(\n  text: string,\n  pos: number,\n  around: boolean,\n  big: boolean,\n  count: number,\n): Span | null {\n  if (text.length === 0) return null;\n  const cls = big ? bigClass : charClass;\n  const p = Math.min(pos, text.length - 1);\n  const c = cls(text[p]);\n  let start = p;\n  while (start > 0 && cls(text[start - 1]) === c) start--;\n  let end = p + 1;\n  while (end < text.length && cls(text[end]) === c) end++;\n\n  // Additional counts extend over following runs.\n  for (let n = 1; n < count; n++) {\n    if (end >= text.length) break;\n    const nc = cls(text[end]);\n    while (end < text.length && cls(text[end]) === nc) end++;\n  }\n\n  if (around) {\n    let trail = end;\n    while (trail < text.length && cls(text[trail]) === 0) trail++;\n    if (trail > end) {\n      end = trail;\n    } else {\n      while (start > 0 && cls(text[start - 1]) === 0) start--;\n    }\n  }\n  return { start, end };\n}\n\nfunction quoteObject(text: string, pos: number, quote: string, around: boolean): Span | null {\n  // Pair quote occurrences left to right, vim-style.\n  const idx: number[] = [];\n  for (let i = 0; i < text.length; i++) if (text[i] === quote) idx.push(i);\n  for (let i = 0; i + 1 < idx.length; i += 2) {\n    const [open, close] = [idx[i], idx[i + 1]];\n    if (pos <= close) {\n      if (!around) return { start: open + 1, end: close };\n      let end = close + 1;\n      let start = open;\n      let trail = end;\n      while (trail < text.length && /\\s/.test(text[trail])) trail++;\n      if (trail > end) end = trail;\n      else while (start > 0 && /\\s/.test(text[start - 1])) start--;\n      return { start, end };\n    }\n  }\n  return null;\n}\n\nfunction bracketObject(text: string, pos: number, key: string, around: boolean): Span | null {\n  const [open, close] = BRACKETS[key];\n  // Find the innermost open bracket at or before the cursor…\n  let depth = 0;\n  let openIdx = -1;\n  for (let i = pos; i >= 0; i--) {\n    const c = text[i];\n    if (c === close && i !== pos) depth++;\n    else if (c === open) {\n      if (depth === 0) {\n        openIdx = i;\n        break;\n      }\n      depth--;\n    }\n  }\n  if (openIdx < 0) return null;\n  // …then its match going forward.\n  depth = 0;\n  for (let i = openIdx + 1; i < text.length; i++) {\n    const c = text[i];\n    if (c === open) depth++;\n    else if (c === close) {\n      if (depth === 0) {\n        return around ? { start: openIdx, end: i + 1 } : { start: openIdx + 1, end: i };\n      }\n      depth--;\n    }\n  }\n  return null;\n}\n\nexport function textObjectSpan(\n  text: string,\n  pos: number,\n  mode: \"i\" | \"a\",\n  obj: string,\n  count: number,\n): Span | null {\n  const around = mode === \"a\";\n  if (obj === \"w\") return wordObject(text, pos, around, false, count);\n  if (obj === \"W\") return wordObject(text, pos, around, true, count);\n  if (QUOTES.has(obj)) return quoteObject(text, pos, obj, around);\n  if (obj in BRACKETS) return bracketObject(text, pos, obj, around);\n  return null;\n}\n","lib/vim/types.ts":"/**\n * The shell-line vim grammar (FLOW.md §6.2). Pure data + pure functions;\n * deliberately independent of the CM6 editor's vim emulation (§8.1).\n */\n\nexport interface VimBuffer {\n  text: string;\n  pos: number;\n}\n\nexport type Operator = \"d\" | \"c\" | \"y\";\n\nexport type PendingInput =\n  | { kind: \"find\"; cmd: \"f\" | \"F\" | \"t\" | \"T\" }\n  | { kind: \"replace\" }\n  | { kind: \"textobj\"; mode: \"i\" | \"a\" };\n\nexport interface LineVimState {\n  count1: string; // count before the operator\n  operator: Operator | null;\n  count2: string; // count after the operator\n  pending: PendingInput | null;\n  register: string; // single unnamed register, characterwise\n  lastFind: { cmd: \"f\" | \"F\" | \"t\" | \"T\"; char: string } | null;\n  lastChange: string[] | null; // key sequence replayed by `.`\n  undo: VimBuffer[];\n  redo: VimBuffer[];\n  /** Keys of the command currently being assembled (for `.` recording). */\n  curKeys: string[];\n}\n\nexport interface KeyInput {\n  key: string;\n  ctrl?: boolean;\n}\n\nexport interface VimResult {\n  buf: VimBuffer;\n  vim: LineVimState;\n  /** Set when the command transitions to INSERT (i a I A s S c…). */\n  mode?: \"INSERT\";\n  /** Signals the integration must act on (the machine knows no history). */\n  effect?: \"history-up\" | \"history-down\" | \"execute\";\n  /** Unrecognized key — flash the status-bar mode indicator (§6.2). */\n  flash?: boolean;\n  handled: boolean;\n}\n","lib/terminal/reducer.ts":"/**\n * All state transitions, pure (FLOW.md §12). The store calls reduce(); tests\n * call it directly.\n */\nimport { normalizePath, windowForPath } from \"@/lib/vfs/path\";\nimport { WINDOW_IDS } from \"@/lib/vfs/types\";\nimport { initialVimState } from \"@/lib/vim/machine\";\nimport { leaf, leafIds, neighbor, removeLeaf, splitLeaf, withRatio } from \"./layout\";\nimport type { Action, AppState, PaneState, WindowId, WindowKey, WindowState } from \"./types\";\n\nexport const MAX_PANES = 4;\n\nexport const HISTORY_SEED = [\"vim resume.md\"];\n\nfunction freshPane(id: string, cwd: string): PaneState {\n  return {\n    id,\n    cwd,\n    prevCwd: cwd,\n    inputBuffer: \"\",\n    cursorPos: 0,\n    historyIndex: null,\n    draft: \"\",\n    scrollback: [],\n    scrollOffset: 0,\n    mode: \"INSERT\",\n    vim: initialVimState(),\n    view: \"shell\",\n    editorPath: null,\n    editorNote: null,\n  };\n}\n\nfunction freshWindow(id: string, cwd: string): WindowState {\n  const paneId = `${id}-p1`;\n  return {\n    visited: false,\n    panes: [freshPane(paneId, cwd)],\n    activePane: paneId,\n    layout: leaf(paneId),\n    zoomed: null,\n  };\n}\n\nexport function initialState(initialWindow: WindowId | null): AppState {\n  const windows = Object.fromEntries(\n    WINDOW_IDS.map((id) => [id, freshWindow(id, `~/${id}`)]),\n  ) as Record<WindowId, WindowState>;\n  return {\n    activeWindow: initialWindow,\n    windows,\n    lobby: freshWindow(\"lobby\", \"~\"),\n    pendingPrefix: false,\n    animating: null,\n    notice: null,\n    pendingConfirm: null,\n    picker: null,\n    overlay: null,\n    crtUnlocked: false,\n    history: [...HISTORY_SEED],\n    nextLineId: 1,\n    nextPaneId: 1,\n    flashNonce: 0,\n  };\n}\n\nexport function getWindow(state: AppState, key: WindowKey): WindowState {\n  return key === \"lobby\" ? state.lobby : state.windows[key];\n}\n\nexport function getPane(state: AppState, key: WindowKey): PaneState {\n  const w = getWindow(state, key);\n  return w.panes.find((p) => p.id === w.activePane) ?? w.panes[0];\n}\n\nexport function getPaneById(state: AppState, key: WindowKey, paneId: string): PaneState | null {\n  return getWindow(state, key).panes.find((p) => p.id === paneId) ?? null;\n}\n\nexport function activeWindowKey(state: AppState): WindowKey {\n  return state.activeWindow ?? \"lobby\";\n}\n\nexport function activePane(state: AppState): PaneState {\n  return getPane(state, activeWindowKey(state));\n}\n\nfunction setWindow(state: AppState, key: WindowKey, next: WindowState): AppState {\n  return key === \"lobby\"\n    ? { ...state, lobby: next }\n    : { ...state, windows: { ...state.windows, [key]: next } };\n}\n\n/** Immutably replace the active pane of one window. */\nfunction withPane(\n  state: AppState,\n  key: WindowKey,\n  update: (pane: PaneState) => PaneState,\n): AppState {\n  const w = getWindow(state, key);\n  const panes = w.panes.map((p) => (p.id === w.activePane ? update(p) : p));\n  return setWindow(state, key, { ...w, panes });\n}\n\nexport function reduce(state: AppState, action: Action): AppState {\n  switch (action.type) {\n    case \"switch-window\":\n      return { ...state, activeWindow: action.window };\n\n    case \"mark-visited\": {\n      const w = state.windows[action.window];\n      return {\n        ...state,\n        windows: { ...state.windows, [action.window]: { ...w, visited: true } },\n      };\n    }\n\n    case \"set-cwd\": {\n      const path = normalizePath(action.path);\n      const target = windowForPath(path);\n      const current = action.windowKey === \"lobby\" ? null : action.windowKey;\n      // FLOW §2.1: paths under another window move you there; ~ and other\n      // window-less paths update the shell you're in and stay.\n      const destKey: WindowKey =\n        target !== null && target !== current ? target : action.windowKey;\n      const moved = withPane(state, destKey, (p) => ({\n        ...p,\n        prevCwd: p.cwd,\n        cwd: path,\n      }));\n      return destKey !== action.windowKey\n        ? { ...moved, activeWindow: target }\n        : moved;\n    }\n\n    case \"append-line\":\n      return {\n        ...withPane(state, action.windowKey, (p) => ({\n          ...p,\n          scrollback: [\n            ...p.scrollback,\n            {\n              id: state.nextLineId,\n              command: action.command,\n              cwd: action.cwd,\n              node: action.node,\n            },\n          ],\n        })),\n        nextLineId: state.nextLineId + 1,\n      };\n\n    case \"clear-scrollback\":\n      return withPane(state, action.windowKey, (p) => ({ ...p, scrollback: [] }));\n\n    case \"set-input\":\n      return withPane(state, action.windowKey, (p) => ({\n        ...p,\n        inputBuffer: action.text,\n        cursorPos: action.cursorPos,\n        historyIndex: null,\n      }));\n\n    case \"history-append\": {\n      if (state.history[state.history.length - 1] === action.line) return state;\n      return { ...state, history: [...state.history, action.line] };\n    }\n\n    case \"history-walk\":\n      return withPane(state, action.windowKey, (p) => {\n        const last = state.history.length - 1;\n        if (action.direction === -1) {\n          const idx = p.historyIndex === null ? last : Math.max(0, p.historyIndex - 1);\n          if (state.history.length === 0) return p;\n          return {\n            ...p,\n            draft: p.historyIndex === null ? p.inputBuffer : p.draft,\n            historyIndex: idx,\n            inputBuffer: state.history[idx],\n            cursorPos: state.history[idx].length,\n          };\n        }\n        if (p.historyIndex === null) return p;\n        if (p.historyIndex >= last) {\n          return { ...p, historyIndex: null, inputBuffer: p.draft, cursorPos: p.draft.length };\n        }\n        const idx = p.historyIndex + 1;\n        return {\n          ...p,\n          historyIndex: idx,\n          inputBuffer: state.history[idx],\n          cursorPos: state.history[idx].length,\n        };\n      });\n\n    case \"set-mode\":\n      return withPane(state, action.windowKey, (p) => ({ ...p, mode: action.mode }));\n\n    case \"set-cursor\":\n      return withPane(state, action.windowKey, (p) => ({ ...p, cursorPos: action.pos }));\n\n    case \"apply-vim\":\n      return withPane(state, action.windowKey, (p) => ({\n        ...p,\n        inputBuffer: action.text,\n        cursorPos: action.pos,\n        vim: action.vim,\n        mode: action.toInsert ? \"INSERT\" : p.mode,\n      }));\n\n    case \"flash-mode\":\n      return { ...state, flashNonce: state.flashNonce + 1 };\n\n    case \"set-notice\":\n      return { ...state, notice: { text: action.text, until: action.until } };\n\n    case \"clear-notice\":\n      return { ...state, notice: null };\n\n    case \"set-confirm\":\n      return { ...state, pendingConfirm: action.confirm };\n\n    case \"set-animating\":\n      return { ...state, animating: action.animating };\n\n    case \"set-pending-prefix\":\n      return { ...state, pendingPrefix: action.pending };\n\n    case \"set-picker\":\n      return { ...state, picker: action.picker };\n\n    case \"set-overlay\":\n      return { ...state, overlay: action.overlay };\n\n    case \"unlock-crt\":\n      return { ...state, crtUnlocked: true };\n\n    case \"open-editor\":\n      return withPane(state, action.windowKey, (p) => ({\n        ...p,\n        view: \"editor\",\n        editorPath: action.path,\n        editorNote: action.note ?? null,\n      }));\n\n    case \"close-editor\":\n      return withPane(state, action.windowKey, (p) => ({\n        ...p,\n        view: \"shell\",\n        editorPath: null,\n        editorNote: null,\n      }));\n\n    case \"split-pane\": {\n      const w = state.windows[action.window];\n      if (w.panes.length >= MAX_PANES) return state;\n      const from = w.panes.find((p) => p.id === w.activePane) ?? w.panes[0];\n      const paneId = `pane-${state.nextPaneId}`;\n      const splitId = `split-${state.nextPaneId}`;\n      const pane = freshPane(paneId, from.cwd);\n      // A short header so the fresh shell states where it is (§7.3).\n      pane.scrollback = [\n        { id: state.nextLineId, command: null, node: `[new pane] ${from.cwd}` },\n      ];\n      const next: WindowState = {\n        ...w,\n        panes: [...w.panes, pane],\n        activePane: paneId,\n        layout: splitLeaf(w.layout, from.id, paneId, action.dir, splitId),\n        zoomed: null,\n      };\n      return {\n        ...setWindow(state, action.window, next),\n        nextPaneId: state.nextPaneId + 1,\n        nextLineId: state.nextLineId + 1,\n      };\n    }\n\n    case \"close-pane\": {\n      const w = state.windows[action.window];\n      if (w.panes.length <= 1) return state;\n      const layout = removeLeaf(w.layout, action.paneId);\n      if (!layout) return state;\n      const remaining = w.panes.filter((p) => p.id !== action.paneId);\n      const active =\n        w.activePane === action.paneId ? leafIds(layout)[0] : w.activePane;\n      return setWindow(state, action.window, {\n        ...w,\n        panes: remaining,\n        activePane: active,\n        layout,\n        zoomed: null,\n      });\n    }\n\n    case \"focus-pane\": {\n      const w = state.windows[action.window];\n      if (!w.panes.some((p) => p.id === action.paneId)) return state;\n      return setWindow(state, action.window, { ...w, activePane: action.paneId });\n    }\n\n    case \"cycle-pane\": {\n      const w = state.windows[action.window];\n      const order = leafIds(w.layout);\n      const idx = order.indexOf(w.activePane);\n      const next = order[(idx + 1) % order.length];\n      return setWindow(state, action.window, { ...w, activePane: next });\n    }\n\n    case \"focus-direction\": {\n      const w = state.windows[action.window];\n      const target = neighbor(w.layout, w.activePane, action.dir);\n      if (!target) return state;\n      return setWindow(state, action.window, { ...w, activePane: target });\n    }\n\n    case \"zoom-pane\": {\n      const w = state.windows[action.window];\n      if (w.panes.length <= 1) return state;\n      return setWindow(state, action.window, {\n        ...w,\n        zoomed: w.zoomed === w.activePane ? null : w.activePane,\n      });\n    }\n\n    case \"set-ratio\": {\n      const w = state.windows[action.window];\n      const ratio = Math.max(0.1, Math.min(0.9, action.ratio));\n      return setWindow(state, action.window, {\n        ...w,\n        layout: withRatio(w.layout, action.splitId, ratio),\n      });\n    }\n  }\n}\n","lib/terminal/executor.tsx":"/**\n * The one command executor (FLOW.md §12.1). Typed lines, clicked tabs,\n * clickable output, and keybinding-driven navigation all end up here; there\n * is no second code path that mutates terminal state.\n */\nimport type { ReactNode } from \"react\";\nimport {\n  commandMetas,\n  resolveCommand,\n  type CommandContext,\n} from \"@/lib/commands/registry\";\nimport { listDir, readFile, resolveNode } from \"@/lib/vfs/tree\";\nimport { resolvePath } from \"@/lib/vfs/path\";\nimport { ErrorLine } from \"@/components/content/messages\";\nimport { CmdLink } from \"@/components/terminal/output/CmdLink\";\nimport { activeWindowKey, getPane } from \"./reducer\";\nimport { store } from \"./store\";\nimport { getThemeEnv } from \"./env\";\nimport { levenshtein } from \"./levenshtein\";\nimport { setRunClickImpl, runClick } from \"./run-click\";\nimport type { WindowId, WindowKey } from \"./types\";\n\nexport interface ExecOptions {\n  source: \"typed\" | \"click\" | \"auto\";\n  /** Run in a specific shell instead of the active one (auto-display). */\n  windowKey?: WindowKey;\n}\n\n/** First-entry auto-display commands (FLOW.md §2.1). */\nexport const AUTO_DISPLAY: Record<WindowId, string> = {\n  about: \"cat about.md\",\n  projects: \"ls\",\n  resume: \"cat resume.md\",\n  contact: \"cat contact.md\",\n  help: \"cat guide.md\",\n};\n\nconst SECTION_WORDS = new Set([\"about\", \"projects\", \"resume\", \"contact\"]);\n\nfunction UnknownCommand({ name }: { name: string }) {\n  if (SECTION_WORDS.has(name)) {\n    // Absolute path so the suggestion works from any cwd.\n    return (\n      <ErrorLine>\n        command not found: {name} — did you mean <CmdLink cmd={`cd ~/${name}`} />?\n      </ErrorLine>\n    );\n  }\n  const near = commandMetas\n    .filter((m) => !m.hidden)\n    .map((m) => m.name)\n    .find((n) => levenshtein(n, name.toLowerCase()) === 1);\n  if (near) {\n    return (\n      <ErrorLine>\n        command not found: {name} (did you mean {\"'\"}\n        <CmdLink cmd={near} />\n        {\"'\"}?)\n      </ErrorLine>\n    );\n  }\n  return (\n    <ErrorLine>\n      command not found: {name} — try {\"'\"}\n      <CmdLink cmd=\"help\" />\n      {\"'\"}\n    </ErrorLine>\n  );\n}\n\n/** After any navigation: first activation of a window auto-runs its command. */\nexport function ensureWindowDisplayed(): void {\n  const state = store.getState();\n  const win = state.activeWindow;\n  if (!win || state.windows[win].visited) return;\n  store.dispatch({ type: \"mark-visited\", window: win });\n  executeCommand(AUTO_DISPLAY[win], { source: \"auto\", windowKey: win });\n}\n\nexport function executeCommand(line: string, opts: ExecOptions): void {\n  const trimmed = line.trim();\n  if (!trimmed) return;\n\n  const startState = store.getState();\n  const windowKey = opts.windowKey ?? activeWindowKey(startState);\n\n  // History expansion: !{n}\n  let cmdLine = trimmed;\n  const bang = /^!(\\d+)$/.exec(trimmed);\n  if (bang) {\n    const entry = startState.history[Number(bang[1]) - 1];\n    if (!entry) {\n      store.dispatch({ type: \"append-line\", windowKey, command: trimmed, node: null });\n      store.dispatch({\n        type: \"append-line\",\n        windowKey,\n        command: null,\n        node: <ErrorLine>{trimmed}: event not found</ErrorLine>,\n      });\n      return;\n    }\n    cmdLine = entry;\n  }\n\n  // Vim habits at the shell prompt (EASTER_EGGS §2).\n  if (cmdLine === \":q\" || cmdLine === \":q!\") {\n    store.dispatch({ type: \"append-line\", windowKey, command: cmdLine, node: null });\n    store.dispatch({\n      type: \"append-line\",\n      windowKey,\n      command: null,\n      node: <p className=\"text-fg\">you&apos;re not in vim. yet.</p>,\n    });\n    store.dispatch({ type: \"history-append\", line: cmdLine });\n    return;\n  }\n  if (cmdLine === \":wq\" || cmdLine === \":x\") {\n    store.dispatch({ type: \"append-line\", windowKey, command: cmdLine, node: null });\n    store.dispatch({\n      type: \"append-line\",\n      windowKey,\n      command: null,\n      node: <p className=\"text-fg\">nothing to write. nothing to quit. take a breath.</p>,\n    });\n    store.dispatch({ type: \"history-append\", line: cmdLine });\n    return;\n  }\n\n  // Echo first — typed and clicked sessions read identically in scrollback.\n  store.dispatch({\n    type: \"append-line\",\n    windowKey,\n    command: cmdLine,\n    cwd: getPane(store.getState(), windowKey).cwd,\n    node: null,\n  });\n\n  const [name, ...args] = cmdLine.split(/\\s+/);\n  const mod = resolveCommand(name);\n\n  let cleared = false;\n  const ctx: CommandContext = {\n    args,\n    raw: cmdLine,\n    get cwd() {\n      return getPane(store.getState(), windowKey).cwd;\n    },\n    get prevCwd() {\n      return getPane(store.getState(), windowKey).prevCwd;\n    },\n    windowKey,\n    resolve: (input) => resolvePath(getPane(store.getState(), windowKey).cwd, input),\n    node: resolveNode,\n    read: readFile,\n    list: listDir,\n    write: (node) =>\n      store.dispatch({ type: \"append-line\", windowKey, command: null, node }),\n    clear: () => {\n      cleared = true;\n    },\n    setCwd: (path) => store.dispatch({ type: \"set-cwd\", windowKey, path }),\n    openEditor: (path, note) =>\n      store.dispatch({ type: \"open-editor\", windowKey, path, note }),\n    notify: (text) =>\n      store.dispatch({ type: \"set-notice\", text, until: Date.now() + 3000 }),\n    confirmOpenUrl: (url) =>\n      store.dispatch({ type: \"set-confirm\", confirm: { kind: \"openUrl\", payload: url } }),\n    startOverlay: (kind) => store.dispatch({ type: \"set-overlay\", overlay: kind }),\n    runClick,\n    history: startState.history,\n    getThemeId: () => getThemeEnv().getThemeId(),\n    setTheme: (id) => getThemeEnv().setTheme(id),\n    commands: commandMetas,\n  };\n\n  const node: ReactNode = mod ? mod.run(ctx) : <UnknownCommand name={name} />;\n\n  if (cleared) {\n    store.dispatch({ type: \"clear-scrollback\", windowKey });\n  } else if (node !== null && node !== undefined) {\n    store.dispatch({ type: \"append-line\", windowKey, command: null, node });\n  }\n\n  store.dispatch({ type: \"history-append\", line: cmdLine });\n\n  // cd into an unvisited window? Its shell runs its first-entry command.\n  ensureWindowDisplayed();\n}\n\n// Default click behavior: execute directly. The animation engine (FLOW §5)\n// replaces this with the type-on version without touching any caller.\nsetRunClickImpl((cmd) => executeCommand(cmd, { source: \"click\" }));\n","lib/terminal/layout.ts":"/**\n * Pane layout as a binary split tree (FLOW §7.3, §12.4). Pure helpers; the\n * reducer owns the state, PaneTree renders the tree with flexbox.\n */\n\nexport type PaneLayout =\n  | { type: \"leaf\"; paneId: string }\n  | {\n      type: \"split\";\n      id: string;\n      dir: \"row\" | \"col\"; // row = side-by-side (%), col = stacked (\")\n      ratio: number; // share of the first child\n      a: PaneLayout;\n      b: PaneLayout;\n    };\n\nexport function leaf(paneId: string): PaneLayout {\n  return { type: \"leaf\", paneId };\n}\n\nexport function leafIds(l: PaneLayout): string[] {\n  return l.type === \"leaf\" ? [l.paneId] : [...leafIds(l.a), ...leafIds(l.b)];\n}\n\n/** Replace the target leaf with a 50/50 split of (old, new). */\nexport function splitLeaf(\n  l: PaneLayout,\n  targetPane: string,\n  newPane: string,\n  dir: \"row\" | \"col\",\n  splitId: string,\n): PaneLayout {\n  if (l.type === \"leaf\") {\n    if (l.paneId !== targetPane) return l;\n    return { type: \"split\", id: splitId, dir, ratio: 0.5, a: l, b: leaf(newPane) };\n  }\n  return {\n    ...l,\n    a: splitLeaf(l.a, targetPane, newPane, dir, splitId),\n    b: splitLeaf(l.b, targetPane, newPane, dir, splitId),\n  };\n}\n\n/** Remove a leaf; its sibling takes the parent split's place. Null = it was the root. */\nexport function removeLeaf(l: PaneLayout, paneId: string): PaneLayout | null {\n  if (l.type === \"leaf\") return l.paneId === paneId ? null : l;\n  const a = removeLeaf(l.a, paneId);\n  if (a === null) return l.b;\n  const b = removeLeaf(l.b, paneId);\n  if (b === null) return a === l.a ? l.a : { ...l, a };\n  return { ...l, a, b };\n}\n\nexport function withRatio(l: PaneLayout, splitId: string, ratio: number): PaneLayout {\n  if (l.type === \"leaf\") return l;\n  if (l.id === splitId) return { ...l, ratio };\n  return { ...l, a: withRatio(l.a, splitId, ratio), b: withRatio(l.b, splitId, ratio) };\n}\n\nexport interface Box {\n  x: number;\n  y: number;\n  w: number;\n  h: number;\n}\n\n/** Each leaf's box on the unit square — for directional focus. */\nexport function paneBoxes(l: PaneLayout, box: Box = { x: 0, y: 0, w: 1, h: 1 }): Map<string, Box> {\n  if (l.type === \"leaf\") return new Map([[l.paneId, box]]);\n  const first =\n    l.dir === \"row\"\n      ? { ...box, w: box.w * l.ratio }\n      : { ...box, h: box.h * l.ratio };\n  const second =\n    l.dir === \"row\"\n      ? { x: box.x + box.w * l.ratio, y: box.y, w: box.w * (1 - l.ratio), h: box.h }\n      : { x: box.x, y: box.y + box.h * l.ratio, w: box.w, h: box.h * (1 - l.ratio) };\n  return new Map([...paneBoxes(l.a, first), ...paneBoxes(l.b, second)]);\n}\n\nexport type Direction = \"left\" | \"right\" | \"up\" | \"down\";\n\n/** The nearest pane in a direction from the given pane, or null. */\nexport function neighbor(l: PaneLayout, from: string, dir: Direction): string | null {\n  const boxes = paneBoxes(l);\n  const me = boxes.get(from);\n  if (!me) return null;\n  const cx = me.x + me.w / 2;\n  const cy = me.y + me.h / 2;\n\n  let best: string | null = null;\n  let bestDist = Infinity;\n  for (const [id, b] of boxes) {\n    if (id === from) continue;\n    const ox = b.x + b.w / 2;\n    const oy = b.y + b.h / 2;\n    const inDir =\n      dir === \"left\" ? ox < cx : dir === \"right\" ? ox > cx : dir === \"up\" ? oy < cy : oy > cy;\n    if (!inDir) continue;\n    const dist = Math.abs(ox - cx) + Math.abs(oy - cy);\n    if (dist < bestDist) {\n      bestDist = dist;\n      best = id;\n    }\n  }\n  return best;\n}\n","lib/terminal/animate.ts":"/**\n * Click-to-command animation (FLOW.md §5) — the teaching mechanism. Every\n * click with a command equivalent types that command into the active pane's\n * prompt, beats, then executes. Module load replaces the executor's direct\n * runClick with this version.\n */\nimport { activeWindowKey, getPane } from \"./reducer\";\nimport { executeCommand } from \"./executor\";\nimport { setRunClickImpl } from \"./run-click\";\nimport { store } from \"./store\";\nimport type { WindowKey } from \"./types\";\n\nconst CHAR_MS = 15;\nconst MAX_TYPE_MS = 250;\nconst BEAT_MS = 60;\n\ninterface Animation {\n  command: string;\n  stash: string;\n  windowKey: WindowKey;\n  shown: number;\n  timer: ReturnType<typeof setInterval> | null;\n  beat: ReturnType<typeof setTimeout> | null;\n}\n\nlet current: Animation | null = null;\n\nfunction execute(anim: Animation): void {\n  executeCommand(anim.command, { source: \"click\", windowKey: anim.windowKey });\n  store.dispatch({\n    type: \"set-input\",\n    windowKey: anim.windowKey,\n    text: anim.stash,\n    cursorPos: anim.stash.length,\n  });\n  store.dispatch({ type: \"set-animating\", animating: null });\n}\n\n/** Complete a running animation instantly (skip rule — keypress or click). */\nexport function finishAnimation(): void {\n  if (!current) return;\n  const anim = current;\n  current = null;\n  if (anim.timer) clearInterval(anim.timer);\n  if (anim.beat) clearTimeout(anim.beat);\n  execute(anim);\n}\n\nfunction prefersReducedMotion(): boolean {\n  return window.matchMedia?.(\"(prefers-reduced-motion: reduce)\").matches ?? false;\n}\n\nexport function animateClick(cmd: string): void {\n  // Never queue: a click during an animation completes it first (§5).\n  finishAnimation();\n\n  const windowKey = activeWindowKey(store.getState());\n  const pane = getPane(store.getState(), windowKey);\n\n  // Clicking in NORMAL or COPY returns to INSERT, then animates (§5).\n  if (pane.mode !== \"INSERT\") {\n    store.dispatch({ type: \"set-mode\", windowKey, mode: \"INSERT\" });\n  }\n\n  if (prefersReducedMotion()) {\n    // The echo is the teaching tool; the animation is garnish.\n    executeCommand(cmd, { source: \"click\", windowKey });\n    return;\n  }\n\n  const anim: Animation = {\n    command: cmd,\n    stash: pane.inputBuffer,\n    windowKey,\n    shown: 0,\n    timer: null,\n    beat: null,\n  };\n  current = anim;\n  store.dispatch({ type: \"set-animating\", animating: { command: cmd, stash: anim.stash } });\n\n  const perChar = Math.min(CHAR_MS, MAX_TYPE_MS / cmd.length);\n  anim.timer = setInterval(() => {\n    anim.shown += 1;\n    store.dispatch({\n      type: \"set-input\",\n      windowKey,\n      text: cmd.slice(0, anim.shown),\n      cursorPos: anim.shown,\n    });\n    if (anim.shown >= cmd.length) {\n      if (anim.timer) clearInterval(anim.timer);\n      anim.timer = null;\n      anim.beat = setTimeout(() => {\n        current = null;\n        execute(anim);\n      }, BEAT_MS);\n    }\n  }, perChar);\n}\n\nsetRunClickImpl(animateClick);\n","lib/terminal/keyboard.ts":"/**\n * One global keyboard listener, capture phase (FLOW.md §6.4, §12.5).\n * Priority: pending confirm → Ctrl+b prefix → prefix table → mode dispatch.\n * Never touches Ctrl+t/w/n, Cmd+anything, or F-keys.\n *\n * INSERT-mode line editing stays on the prompt <input>; NORMAL/COPY arrive\n * with the vim grammar phase and slot in below the prefix handling here.\n */\nimport { WINDOW_IDS, type WindowId } from \"@/lib/vfs/types\";\nimport { handleKey } from \"@/lib/vim/machine\";\nimport { MAX_PANES, activePane, activeWindowKey } from \"./reducer\";\nimport { executeCommand, ensureWindowDisplayed } from \"./executor\";\nimport { finishAnimation } from \"./animate\";\nimport { getThemeEnv } from \"./env\";\nimport { printBindingCheatsheet } from \"./cheatsheet\";\nimport { getScroller, LINE_PX } from \"./scroll-registry\";\nimport { store } from \"./store\";\nimport type { Direction, WindowKey } from \"./types\";\n\nfunction switchWindow(target: WindowId | null): void {\n  store.dispatch({ type: \"switch-window\", window: target });\n  ensureWindowDisplayed();\n}\n\nfunction cycleWindow(delta: 1 | -1): void {\n  const current = store.getState().activeWindow;\n  const idx = current ? WINDOW_IDS.indexOf(current) : delta === 1 ? -1 : 1;\n  const next = (idx + delta + WINDOW_IDS.length) % WINDOW_IDS.length;\n  switchWindow(WINDOW_IDS[next]);\n}\n\nfunction notify(text: string): void {\n  store.dispatch({ type: \"set-notice\", text, until: Date.now() + 3000 });\n}\n\nfunction isDesktop(): boolean {\n  return window.matchMedia?.(\"(min-width: 768px)\").matches ?? true;\n}\n\n/** Refuse splits that would push a pane under ~20 cols / 6 rows (§7.3). */\nconst MIN_PANE_W = 170;\nconst MIN_PANE_H = 132;\n\nfunction trySplit(dir: \"row\" | \"col\"): void {\n  const state = store.getState();\n  if (state.activeWindow !== \"projects\") {\n    return notify(\"splits are available in the projects window\");\n  }\n  if (!isDesktop()) {\n    return notify(\"splits need a wider screen\");\n  }\n  const w = state.windows.projects;\n  if (w.panes.length >= MAX_PANES) {\n    return notify(`pane limit reached (${MAX_PANES})`);\n  }\n  const el = getScroller(`projects:${w.activePane}`);\n  if (el && el.clientWidth > 0) {\n    if (dir === \"row\" && el.clientWidth / 2 < MIN_PANE_W) return notify(\"pane too narrow to split\");\n    if (dir === \"col\" && el.clientHeight / 2 < MIN_PANE_H) return notify(\"pane too short to split\");\n  }\n  store.dispatch({ type: \"split-pane\", window: \"projects\", dir });\n}\n\nconst DIRECTION_KEYS: Record<string, Direction> = {\n  h: \"left\",\n  j: \"down\",\n  k: \"up\",\n  l: \"right\",\n  ArrowLeft: \"left\",\n  ArrowDown: \"down\",\n  ArrowUp: \"up\",\n  ArrowRight: \"right\",\n};\n\nfunction handlePrefixKey(key: string): void {\n  store.dispatch({ type: \"set-pending-prefix\", pending: false });\n  const state = store.getState();\n  const win = state.activeWindow;\n\n  if (key === \"n\") return cycleWindow(1);\n  if (key === \"p\") return cycleWindow(-1);\n  if (key === \"[\") {\n    store.dispatch({ type: \"set-mode\", windowKey: activeWindowKey(state), mode: \"COPY\" });\n    return;\n  }\n  if (key === \"w\") {\n    const index = win ? WINDOW_IDS.indexOf(win) : 0;\n    store.dispatch({ type: \"set-picker\", picker: { index: Math.max(0, index) } });\n    return;\n  }\n  if (key === \"?\") return printBindingCheatsheet();\n  if (key === \"%\") return trySplit(\"row\");\n  if (key === '\"') return trySplit(\"col\");\n  if (key === \"t\") {\n    store.dispatch({ type: \"set-overlay\", overlay: \"clock\" });\n    return;\n  }\n\n  if (win) {\n    const w = state.windows[win];\n    if (key === \"o\") {\n      store.dispatch({ type: \"cycle-pane\", window: win });\n      return;\n    }\n    if (key in DIRECTION_KEYS) {\n      store.dispatch({ type: \"focus-direction\", window: win, dir: DIRECTION_KEYS[key] });\n      return;\n    }\n    if (key === \"z\") {\n      store.dispatch({ type: \"zoom-pane\", window: win });\n      return;\n    }\n    if (key === \"x\") {\n      if (w.panes.length <= 1) return notify(\"can't close the only pane\");\n      store.dispatch({\n        type: \"set-confirm\",\n        confirm: { kind: \"closePane\", payload: w.activePane },\n      });\n      return;\n    }\n  }\n\n  const digit = Number(key);\n  if (digit >= 1 && digit <= WINDOW_IDS.length) {\n    return switchWindow(WINDOW_IDS[digit - 1]);\n  }\n  // Any unbound key cancels the prefix silently (§6.4).\n}\n\n/** Keys while the Ctrl+b w picker is open. */\nfunction handlePickerKey(e: KeyboardEvent): void {\n  const picker = store.getState().picker!;\n  e.preventDefault();\n  if (e.key === \"j\" || e.key === \"ArrowDown\") {\n    store.dispatch({\n      type: \"set-picker\",\n      picker: { index: Math.min(WINDOW_IDS.length - 1, picker.index + 1) },\n    });\n    return;\n  }\n  if (e.key === \"k\" || e.key === \"ArrowUp\") {\n    store.dispatch({ type: \"set-picker\", picker: { index: Math.max(0, picker.index - 1) } });\n    return;\n  }\n  if (e.key === \"Enter\") {\n    store.dispatch({ type: \"set-picker\", picker: null });\n    switchWindow(WINDOW_IDS[picker.index]);\n    return;\n  }\n  const digit = Number(e.key);\n  if (digit >= 1 && digit <= WINDOW_IDS.length) {\n    store.dispatch({ type: \"set-picker\", picker: null });\n    switchWindow(WINDOW_IDS[digit - 1]);\n    return;\n  }\n  if (e.key === \"Escape\" || e.key === \"q\" || e.key === \"w\") {\n    store.dispatch({ type: \"set-picker\", picker: null });\n  }\n}\n\n// ---- COPY mode (FLOW §6.3): keyboard scrollback navigation. ---------------\n\nlet copyCount = \"\"; // {count}G\nlet copyPendingG = false; // gg\n\nfunction activeScroller(windowKey: WindowKey): HTMLElement | undefined {\n  return getScroller(`${windowKey}:${activePane(store.getState()).id}`);\n}\n\nfunction exitCopy(windowKey: WindowKey): void {\n  copyCount = \"\";\n  copyPendingG = false;\n  store.dispatch({ type: \"set-mode\", windowKey, mode: \"INSERT\" });\n  const el = activeScroller(windowKey);\n  if (el) el.scrollTop = el.scrollHeight; // re-pin to bottom (§6.3)\n}\n\nfunction handleCopyKey(e: KeyboardEvent, windowKey: WindowKey): void {\n  const el = activeScroller(windowKey);\n  const scrollBy = (px: number) => {\n    if (!el) return;\n    el.scrollTop = Math.max(0, Math.min(el.scrollHeight, el.scrollTop + px));\n  };\n  const page = el ? el.clientHeight : 0;\n\n  if (e.ctrlKey) {\n    e.preventDefault();\n    if (e.key === \"d\") return scrollBy(page / 2);\n    if (e.key === \"u\") return scrollBy(-page / 2);\n    if (e.key === \"f\") return scrollBy(page);\n    if (e.key === \"b\") return scrollBy(-page);\n    return;\n  }\n\n  e.preventDefault();\n  const key = e.key;\n\n  if (copyPendingG) {\n    copyPendingG = false;\n    if (key === \"g\" && el) el.scrollTop = 0; // gg\n    return;\n  }\n  if (/^[0-9]$/.test(key)) {\n    copyCount += key;\n    return;\n  }\n  switch (key) {\n    case \"j\":\n      return scrollBy(LINE_PX);\n    case \"k\":\n      return scrollBy(-LINE_PX);\n    case \"g\":\n      copyPendingG = true;\n      return;\n    case \"G\":\n      if (el) {\n        el.scrollTop = copyCount ? (parseInt(copyCount, 10) - 1) * LINE_PX : el.scrollHeight;\n      }\n      copyCount = \"\";\n      return;\n    case \"q\":\n    case \"Escape\":\n    case \"Enter\":\n      return exitCopy(windowKey);\n    default:\n      copyCount = \"\";\n  }\n}\n\n// ---- NORMAL mode (FLOW §6.2): feed the vim machine. -----------------------\n\nfunction handleNormalKey(e: KeyboardEvent, windowKey: WindowKey): void {\n  // Modifier combos other than plain Ctrl+r are not vim's business.\n  if (e.altKey || (e.ctrlKey && e.key !== \"r\")) return;\n  if (e.key.length !== 1 && ![\"Escape\", \"Enter\", \"ArrowUp\", \"ArrowDown\"].includes(e.key)) {\n    return; // Shift, Tab, Home… leave defaults alone\n  }\n  e.preventDefault();\n\n  const pane = activePane(store.getState());\n  const result = handleKey(\n    { text: pane.inputBuffer, pos: pane.cursorPos },\n    pane.vim,\n    { key: e.key, ctrl: e.ctrlKey },\n  );\n\n  if (result.effect === \"execute\") {\n    const line = result.buf.text;\n    store.dispatch({\n      type: \"apply-vim\",\n      windowKey,\n      text: \"\",\n      pos: 0,\n      vim: result.vim,\n      toInsert: true,\n    });\n    executeCommand(line, { source: \"typed\" });\n    return;\n  }\n\n  store.dispatch({\n    type: \"apply-vim\",\n    windowKey,\n    text: result.buf.text,\n    pos: result.buf.pos,\n    vim: result.vim,\n    toInsert: result.mode === \"INSERT\",\n  });\n\n  if (result.effect === \"history-up\") {\n    store.dispatch({ type: \"history-walk\", windowKey, direction: -1 });\n  } else if (result.effect === \"history-down\") {\n    store.dispatch({ type: \"history-walk\", windowKey, direction: 1 });\n  }\n  if (result.flash) store.dispatch({ type: \"flash-mode\" });\n}\n\n// Konami code (EASTER_EGGS §3): passive observation, desktop only.\nconst KONAMI = [\n  \"ArrowUp\",\n  \"ArrowUp\",\n  \"ArrowDown\",\n  \"ArrowDown\",\n  \"ArrowLeft\",\n  \"ArrowRight\",\n  \"ArrowLeft\",\n  \"ArrowRight\",\n  \"b\",\n  \"a\",\n];\nexport const CRT_UNLOCK_KEY = \"portfolio:crt-unlocked\";\nlet konamiProgress = 0;\n\nfunction watchKonami(key: string): void {\n  konamiProgress = key === KONAMI[konamiProgress] ? konamiProgress + 1 : key === KONAMI[0] ? 1 : 0;\n  if (konamiProgress < KONAMI.length) return;\n  konamiProgress = 0;\n  store.dispatch({ type: \"unlock-crt\" });\n  try {\n    localStorage.setItem(CRT_UNLOCK_KEY, \"1\");\n  } catch {\n    /* private mode — the unlock still applies this session */\n  }\n  notify(\"theme unlocked: crt\");\n  getThemeEnv().setTheme(\"crt\");\n}\n\nexport function initKeyboard(): () => void {\n  const onKeyDown = (e: KeyboardEvent) => {\n    // Hands off the browser's keys (§6.4).\n    if (e.metaKey) return;\n    if (e.ctrlKey && [\"t\", \"w\", \"n\"].includes(e.key.toLowerCase())) return;\n    if (/^F\\d+$/.test(e.key)) return;\n\n    if (!e.ctrlKey && !e.altKey) watchKonami(e.key);\n\n    const state = store.getState();\n\n    // Any input dismisses a full-pane overlay (clock, sl, …).\n    if (state.overlay) {\n      e.preventDefault();\n      e.stopPropagation();\n      store.dispatch({ type: \"set-overlay\", overlay: null });\n      return;\n    }\n\n    // A keypress during a click animation completes it instantly (§5).\n    if (state.animating) {\n      e.preventDefault();\n      finishAnimation();\n      return;\n    }\n\n    // Window picker swallows navigation keys while open.\n    if (state.picker) {\n      handlePickerKey(e);\n      return;\n    }\n\n    // Pending status-bar confirm consumes y/n (FLOW §10.2).\n    if (state.pendingConfirm && !e.ctrlKey && !e.altKey) {\n      if (e.key === \"y\" || e.key === \"Y\") {\n        if (state.pendingConfirm.kind === \"openUrl\") {\n          window.open(state.pendingConfirm.payload, \"_blank\", \"noopener,noreferrer\");\n        } else if (state.pendingConfirm.kind === \"closePane\" && state.activeWindow) {\n          store.dispatch({\n            type: \"close-pane\",\n            window: state.activeWindow,\n            paneId: state.pendingConfirm.payload,\n          });\n        }\n        store.dispatch({ type: \"set-confirm\", confirm: null });\n        e.preventDefault();\n        return;\n      }\n      if (e.key === \"n\" || e.key === \"N\" || e.key === \"Escape\") {\n        store.dispatch({ type: \"set-confirm\", confirm: null });\n        e.preventDefault();\n        return;\n      }\n      return;\n    }\n\n    // Ctrl+b: the tmux prefix, consumed in all modes and views — including\n    // inside the editor; stopPropagation keeps it from CodeMirror (§6.4).\n    if (e.ctrlKey && !e.altKey && e.key.toLowerCase() === \"b\") {\n      e.preventDefault();\n      e.stopPropagation();\n      store.dispatch({ type: \"set-pending-prefix\", pending: true });\n      return;\n    }\n\n    if (state.pendingPrefix) {\n      e.preventDefault();\n      e.stopPropagation();\n      if (e.key === \"Escape\") {\n        store.dispatch({ type: \"set-pending-prefix\", pending: false });\n        return;\n      }\n      handlePrefixKey(e.key);\n      return;\n    }\n\n    // Mode dispatch for the active pane (§6.4 priority order).\n    const windowKey = activeWindowKey(state);\n    const pane = activePane(state);\n    if (pane.view === \"editor\") {\n      // CodeMirror's vim owns everything else while a file is open.\n      return;\n    }\n    if (pane.mode === \"COPY\") {\n      handleCopyKey(e, windowKey);\n      return;\n    }\n    if (pane.mode === \"NORMAL\") {\n      handleNormalKey(e, windowKey);\n      return;\n    }\n\n    // Ctrl+l clears the active pane (INSERT affordance, §6.1).\n    if (e.ctrlKey && !e.altKey && e.key.toLowerCase() === \"l\") {\n      e.preventDefault();\n      store.dispatch({ type: \"clear-scrollback\", windowKey: activeWindowKey(state) });\n      return;\n    }\n  };\n\n  window.addEventListener(\"keydown\", onKeyDown, true);\n  return () => window.removeEventListener(\"keydown\", onKeyDown, true);\n}\n","lib/vfs/tree.ts":"/**\n * The virtual filesystem: one plain typed tree built at module load\n * (FLOW.md §2, §12.3). No async, no fetching — commands resolve paths\n * against this synchronously.\n */\nimport { projects } from \"@/data/projects\";\nimport { siteSource } from \"@/data/generated/site-source\";\nimport { experience } from \"@/data/resume\";\nimport { bashrc, nothingToSeeHere, vimrc } from \"@/data/dotfiles\";\nimport { commandsMd, guideMd, keybindingsMd } from \"@/data/help-docs\";\nimport { profile } from \"@/data/profile\";\nimport {\n  aboutMd,\n  contactMd,\n  etcPasswd,\n  experiencePageMd,\n  planText,\n  projectReadmeMd,\n  resumeMd,\n  resumePdfSummary,\n  slugify,\n  usesMd,\n} from \"./builders\";\nimport { HOME, normalizePath } from \"./path\";\nimport type { VfsDir, VfsFile, VfsLanguage, VfsNode } from \"./types\";\n\nfunction file(\n  name: string,\n  raw: string,\n  extra: Partial<Omit<VfsFile, \"kind\" | \"name\" | \"raw\">> = {},\n): VfsFile {\n  const language: VfsLanguage = extra.language ?? (name.endsWith(\".md\") ? \"markdown\" : \"text\");\n  return { kind: \"file\", name, raw, ...extra, language };\n}\n\nfunction dir(name: string, children: VfsNode[], extra: Partial<VfsDir> = {}): VfsDir {\n  return { kind: \"dir\", name, children, ...extra };\n}\n\nconst EXT_LANGUAGE: Record<string, VfsLanguage> = {\n  ts: \"typescript\",\n  tsx: \"tsx\",\n  js: \"javascript\",\n  jsx: \"javascript\",\n  mjs: \"javascript\",\n  cjs: \"javascript\",\n  json: \"json\",\n  css: \"css\",\n  html: \"html\",\n  md: \"markdown\",\n};\n\nfunction languageFor(name: string): VfsLanguage {\n  const ext = name.split(\".\").pop() ?? \"\";\n  return EXT_LANGUAGE[ext] ?? \"text\";\n}\n\n/** Build a project's src/ tree from its bundled files (FLOW §8). */\nfunction srcTree(files: Record<string, string>): VfsDir {\n  const root = dir(\"src\", []);\n  for (const [path, raw] of Object.entries(files)) {\n    const segments = path.split(\"/\");\n    const name = segments.pop()!;\n    let cursor = root;\n    for (const seg of segments) {\n      let next = cursor.children.find(\n        (c): c is VfsDir => c.kind === \"dir\" && c.name === seg,\n      );\n      if (!next) {\n        next = dir(seg, []);\n        cursor.children.push(next);\n      }\n      cursor = next;\n    }\n    cursor.children.push(file(name, raw, { language: languageFor(name) }));\n  }\n  return root;\n}\n\nfunction buildHome(): VfsDir {\n  return dir(\"christian\", [\n    dir(\"about\", [\n      file(\"about.md\", aboutMd(), { render: \"about\" }),\n      file(\"uses.md\", usesMd(), { render: \"uses\" }),\n    ]),\n    dir(\n      \"projects\",\n      projects.map((p) => {\n        const bundled = siteSource[p.slug];\n        return dir(p.slug, [\n          file(\"README.md\", projectReadmeMd(p), { render: \"project-readme\" }),\n          ...(bundled ? [srcTree(bundled)] : []),\n        ]);\n      }),\n    ),\n    dir(\"resume\", [\n      file(\"resume.md\", resumeMd(), { render: \"resume\" }),\n      file(\"resume.pdf\", resumePdfSummary(), { download: profile.resumePdf }),\n      dir(\n        \"experience\",\n        experience.map((e) => file(`${slugify(e.org)}.md`, experiencePageMd(e))),\n      ),\n    ]),\n    dir(\"contact\", [file(\"contact.md\", contactMd(), { render: \"contact\" })]),\n    dir(\"help\", [\n      file(\"guide.md\", guideMd),\n      file(\"commands.md\", commandsMd),\n      file(\"keybindings.md\", keybindingsMd),\n    ]),\n    file(\".bashrc\", bashrc, { hidden: true }),\n    file(\".plan\", planText(), { hidden: true }),\n    file(\".vimrc\", vimrc, { hidden: true }),\n    dir(\".secrets\", [file(\"nothing_to_see_here.txt\", nothingToSeeHere)], { hidden: true }),\n  ]);\n}\n\nconst ROOT: VfsDir = dir(\"/\", [\n  dir(\"home\", [buildHome()]),\n  dir(\"etc\", [file(\"passwd\", etcPasswd())]),\n]);\n\n/** Resolve a canonical-or-not path to its node; null = ENOENT. */\nexport function resolveNode(path: string): VfsNode | null {\n  const normalized = normalizePath(path);\n  const absolute = normalized === \"~\" ? HOME : normalized.startsWith(\"~/\")\n    ? HOME + normalized.slice(1)\n    : normalized;\n\n  let node: VfsNode = ROOT;\n  for (const seg of absolute.split(\"/\").filter(Boolean)) {\n    if (node.kind !== \"dir\") return null;\n    const next: VfsNode | undefined = node.children.find((c) => c.name === seg);\n    if (!next) return null;\n    node = next;\n  }\n  return node;\n}\n\nexport function readFile(path: string): VfsFile | null {\n  const node = resolveNode(path);\n  return node?.kind === \"file\" ? node : null;\n}\n\nexport function listDir(path: string): VfsNode[] | null {\n  const node = resolveNode(path);\n  return node?.kind === \"dir\" ? node.children : null;\n}\n","lib/vfs/path.ts":"import { WINDOW_IDS, type WindowId } from \"./types\";\n\n/** The real location ~ abbreviates. */\nexport const HOME = \"/home/christian\";\n\n/**\n * Canonical form: paths inside the home directory are ~-rooted\n * (\"~\", \"~/projects/foo\"); everything else is absolute (\"/\", \"/etc/passwd\").\n */\nexport function normalizePath(path: string): string {\n  const expanded =\n    path === \"~\" ? HOME : path.startsWith(\"~/\") ? HOME + path.slice(1) : path;\n\n  const out: string[] = [];\n  for (const seg of expanded.split(\"/\")) {\n    if (seg === \"\" || seg === \".\") continue;\n    if (seg === \"..\") out.pop();\n    else out.push(seg);\n  }\n\n  const abs = \"/\" + out.join(\"/\");\n  if (abs === HOME) return \"~\";\n  if (abs.startsWith(HOME + \"/\")) return \"~\" + abs.slice(HOME.length);\n  return abs;\n}\n\n/** Resolve user input against a cwd; empty input stays put. */\nexport function resolvePath(cwd: string, input: string): string {\n  const trimmed = input.trim();\n  if (!trimmed) return normalizePath(cwd);\n  if (trimmed.startsWith(\"~\") || trimmed.startsWith(\"/\")) return normalizePath(trimmed);\n  return normalizePath(cwd + \"/\" + trimmed);\n}\n\n/** The window a path belongs to — top-level dirs under ~ are windows (§2.1). */\nexport function windowForPath(path: string): WindowId | null {\n  const normalized = normalizePath(path);\n  if (!normalized.startsWith(\"~/\")) return null;\n  const top = normalized.slice(2).split(\"/\")[0];\n  return (WINDOW_IDS as readonly string[]).includes(top) ? (top as WindowId) : null;\n}\n","lib/vfs/builders.ts":"/**\n * Markdown/text generators for virtual filesystem files. Content stays\n * single-source in data/ — these templates turn the typed objects into the\n * raw text the vim viewer shows and `cat` falls back to.\n */\nimport { profile } from \"@/data/profile\";\nimport { socials } from \"@/data/socials\";\nimport { now } from \"@/data/now\";\nimport { uses } from \"@/data/uses\";\nimport { education, experience, skills, type ResumeEntry } from \"@/data/resume\";\nimport type { Project } from \"@/data/projects\";\n\nexport function slugify(text: string): string {\n  return text\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, \"-\")\n    .replace(/^-+|-+$/g, \"\");\n}\n\nexport function aboutMd(): string {\n  return [\n    `# ${profile.name}`,\n    \"\",\n    `> ${profile.tagline}`,\n    \"\",\n    `**${profile.role}** · ${profile.location}`,\n    \"\",\n    ...profile.about.flatMap((p) => [p, \"\"]),\n    `More: [uses.md](uses.md) — the tools this gets built with.`,\n  ].join(\"\\n\");\n}\n\nexport function usesMd(): string {\n  const sections = uses.flatMap((g) => [\n    `## ${g.group}`,\n    \"\",\n    ...g.items.map((i) => `- ${i}`),\n    \"\",\n  ]);\n  return [\"# Uses\", \"\", \"The gear and software I rely on.\", \"\", ...sections].join(\"\\n\");\n}\n\nfunction resumeEntryMd(e: ResumeEntry): string[] {\n  const where = e.location ? ` · ${e.location}` : \"\";\n  return [\n    `### ${e.title} — ${e.org}`,\n    \"\",\n    `${e.start}–${e.end}${where}`,\n    \"\",\n    ...e.bullets.map((b) => `- ${b}`),\n    \"\",\n  ];\n}\n\nexport function resumeMd(): string {\n  return [\n    `# Resume — ${profile.name}`,\n    \"\",\n    `${profile.role} · ${profile.location} · ${profile.email}`,\n    \"\",\n    \"## Experience\",\n    \"\",\n    ...experience.flatMap(resumeEntryMd),\n    \"## Education\",\n    \"\",\n    ...education.flatMap(resumeEntryMd),\n    \"## Skills\",\n    \"\",\n    ...skills.map((s) => `- **${s.group}:** ${s.items.join(\", \")}`),\n    \"\",\n    `Per-role detail lives in [experience/](experience/). PDF: [resume.pdf](resume.pdf).`,\n  ].join(\"\\n\");\n}\n\nexport function resumePdfSummary(): string {\n  return [\n    `${profile.name} — ${profile.role}`,\n    \"\",\n    \"This is a PDF. The terminal prints this summary; click the file name\",\n    \"(or the link below) to download the real thing.\",\n  ].join(\"\\n\");\n}\n\nexport function experiencePageMd(e: ResumeEntry): string {\n  const where = e.location ? ` · ${e.location}` : \"\";\n  return [\n    `# ${e.org}`,\n    \"\",\n    `**${e.title}** · ${e.start}–${e.end}${where}`,\n    \"\",\n    ...e.bullets.map((b) => `- ${b}`),\n    \"\",\n    \"Back to the overview: [../resume.md](../resume.md)\",\n  ].join(\"\\n\");\n}\n\nexport function contactMd(): string {\n  const rows = socials.map((s) => `- **${s.label}:** [${s.handle}](${s.url})`);\n  return [\n    \"# Contact\",\n    \"\",\n    `The fastest way is email: [${profile.email}](mailto:${profile.email})`,\n    \"\",\n    ...rows,\n    `- **Homelab:** [dashboard](${profile.homelabUrl})`,\n    \"\",\n    \"No forms, no funnels. A reply is usually quick.\",\n  ].join(\"\\n\");\n}\n\nexport function planText(): string {\n  return [\n    `Last update: ${now.updated}`,\n    \"\",\n    ...now.items.map((i) => `* ${i}`),\n  ].join(\"\\n\");\n}\n\nexport function projectReadmeMd(p: Project): string {\n  if (p.readme) return p.readme;\n  const links: string[] = [];\n  if (p.liveUrl) links.push(`**Live:** ${p.liveUrl}`);\n  if (p.sourceUrl) links.push(`**Source:** ${p.sourceUrl}`);\n  return [\n    `# ${p.title}`,\n    \"\",\n    p.pitch,\n    \"\",\n    ...(p.description ? [p.description, \"\"] : []),\n    `**Stack:** ${p.stack.join(\" · \")}`,\n    \"\",\n    ...(links.length ? [links.join(\" · \"), \"\"] : []),\n  ].join(\"\\n\");\n}\n\nexport function etcPasswd(): string {\n  return [\n    \"root:x:0:0:root:/root:/bin/zsh\",\n    `christian:x:1000:1000:${profile.name}:/home/christian:/bin/zsh`,\n    \"impostor_syndrome:x:1001:1001:visits occasionally:/home/christian:/bin/zsh\",\n    \"coffee:x:1002:1002:load-bearing:/var/lib/coffee:/usr/sbin/nologin\",\n    \"visitor:x:1003:1003:hello there:/tmp:/bin/zsh\",\n  ].join(\"\\n\");\n}\n","components/terminal/Terminal.tsx":"\"use client\";\n\nimport { useEffect, useRef } from \"react\";\nimport { TitleBar } from \"./TitleBar\";\nimport { TabBar } from \"./TabBar\";\nimport { WindowArea } from \"./WindowArea\";\nimport { WindowPicker } from \"./WindowPicker\";\nimport { StatusBar } from \"./StatusBar\";\nimport { seedMotd } from \"./Motd\";\nimport { useTheme } from \"@/components/theme/ThemeProvider\";\nimport { CrtOverlay } from \"@/components/effects/CrtOverlay\";\nimport { Disintegration } from \"@/components/effects/Disintegration\";\nimport { MatrixRain } from \"@/components/effects/MatrixRain\";\nimport { store } from \"@/lib/terminal/store\";\nimport { executeCommand } from \"@/lib/terminal/executor\";\nimport { initIdle } from \"@/lib/terminal/idle\";\nimport { initKeyboard } from \"@/lib/terminal/keyboard\";\nimport { initRouting } from \"@/lib/terminal/routing\";\nimport { registerThemeEnv } from \"@/lib/terminal/env\";\nimport { useTerminalStore } from \"@/lib/terminal/useTerminalStore\";\nimport type { WindowId } from \"@/lib/terminal/types\";\n\n/**\n * The terminal shell — a thin layout over the store (FLOW.md §1). All state\n * lives in lib/terminal; this component boots the session and renders chrome.\n */\nexport function Terminal({ initialWindow = null }: { initialWindow?: WindowId | null }) {\n  const { themeId, setTheme } = useTheme();\n\n  // Bridge the theme context to the non-React executor.\n  const themeIdRef = useRef(themeId);\n  useEffect(() => {\n    themeIdRef.current = themeId;\n  }, [themeId]);\n  useEffect(() => {\n    registerThemeEnv({ getThemeId: () => themeIdRef.current, setTheme });\n  }, [setTheme]);\n\n  // Boot once: MOTD in the landing shell, deep links arrive \"as if typed\"\n  // (FLOW §4), then the global listeners. If hydration fails this never runs\n  // and the server-rendered fallback stays visible.\n  useEffect(() => {\n    document.documentElement.setAttribute(\"data-js-ready\", \"true\");\n\n    store.reset(initialWindow);\n    try {\n      if (localStorage.getItem(\"portfolio:crt-unlocked\") === \"1\") {\n        store.dispatch({ type: \"unlock-crt\" });\n      }\n    } catch {\n      /* storage unavailable */\n    }\n    seedMotd(initialWindow ?? \"lobby\");\n    if (initialWindow) {\n      executeCommand(`cd ~/${initialWindow}`, { source: \"auto\", windowKey: initialWindow });\n    }\n\n    const disposeKeyboard = initKeyboard();\n    const disposeRouting = initRouting();\n    const disposeIdle = initIdle();\n    return () => {\n      disposeKeyboard();\n      disposeRouting();\n      disposeIdle();\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const overlay = useTerminalStore((s) => s.overlay);\n\n  return (\n    <div data-terminal-root className=\"relative flex h-dvh flex-col bg-window\">\n      <TitleBar />\n      <TabBar />\n      <WindowArea />\n      <StatusBar />\n      <WindowPicker />\n      <CrtOverlay />\n      {overlay === \"disintegration\" && <Disintegration />}\n      {overlay === \"matrix\" && <MatrixRain />}\n    </div>\n  );\n}\n","components/terminal/PaneTree.tsx":"\"use client\";\n\nimport { useRef, type MouseEvent, type PointerEvent } from \"react\";\nimport { CopyIndicator } from \"./CopyIndicator\";\nimport { PaneScrollback } from \"./PaneScrollback\";\nimport { Prompt } from \"./Prompt\";\nimport { VimViewer } from \"@/components/editor/VimViewer\";\nimport { TmuxClock } from \"@/components/effects/TmuxClock\";\nimport { SlTrain } from \"@/components/effects/SlTrain\";\nimport { TopTable } from \"@/components/effects/TopTable\";\nimport { registerScroller } from \"@/lib/terminal/scroll-registry\";\nimport { activeWindowKey, getPaneById, getWindow } from \"@/lib/terminal/reducer\";\nimport { store } from \"@/lib/terminal/store\";\nimport { useTerminalStore } from \"@/lib/terminal/useTerminalStore\";\nimport type { PaneLayout, WindowId, WindowKey } from \"@/lib/terminal/types\";\n\nfunction PaneView({\n  windowKey,\n  paneId,\n  framed,\n}: {\n  windowKey: WindowKey;\n  paneId: string;\n  framed: boolean;\n}) {\n  const isActive = useTerminalStore((s) => getWindow(s, windowKey).activePane === paneId);\n  const view = useTerminalStore((s) => getPaneById(s, windowKey, paneId)?.view ?? \"shell\");\n  const editorPath = useTerminalStore(\n    (s) => getPaneById(s, windowKey, paneId)?.editorPath ?? null,\n  );\n  const editorNote = useTerminalStore(\n    (s) => getPaneById(s, windowKey, paneId)?.editorNote ?? null,\n  );\n  const overlay = useTerminalStore((s) =>\n    activeWindowKey(s) === windowKey && getWindow(s, windowKey).activePane === paneId\n      ? s.overlay\n      : null,\n  );\n\n  const onClick = (e: MouseEvent<HTMLDivElement>) => {\n    if (windowKey !== \"lobby\" && !isActive) {\n      store.dispatch({ type: \"focus-pane\", window: windowKey as WindowId, paneId });\n    }\n    if (view === \"editor\") return;\n    if (window.getSelection()?.toString()) return;\n    if ((e.target as HTMLElement).closest(\"a,button,select,input,textarea,label\")) return;\n    e.currentTarget\n      .querySelector<HTMLInputElement>(\"input[aria-label='Terminal command input']\")\n      ?.focus({ preventScroll: true });\n  };\n\n  return (\n    <div\n      data-pane-scroll\n      data-pane-id={paneId}\n      ref={(el) => registerScroller(`${windowKey}:${paneId}`, el)}\n      onClick={onClick}\n      className={[\n        \"relative min-h-0 min-w-0 flex-1\",\n        view === \"editor\" ? \"overflow-hidden\" : \"space-y-4 overflow-y-auto px-4 py-4 sm:px-5\",\n        // Active pane: bright border; inactive: dim (§7.3) — only when split.\n        framed ? \"border\" : \"\",\n        framed && isActive ? \"border-accent\" : framed ? \"border-border\" : \"\",\n      ].join(\" \")}\n    >\n      {view === \"editor\" && editorPath ? (\n        <VimViewer windowKey={windowKey} paneId={paneId} path={editorPath} note={editorNote} />\n      ) : (\n        <>\n          <CopyIndicator windowKey={windowKey} paneId={paneId} />\n          <PaneScrollback windowKey={windowKey} paneId={paneId} />\n          <Prompt windowKey={windowKey} paneId={paneId} />\n        </>\n      )}\n      {overlay === \"clock\" && <TmuxClock />}\n      {overlay === \"sl\" && <SlTrain />}\n      {(overlay === \"top\" || overlay === \"htop\") && <TopTable fancy={overlay === \"htop\"} />}\n    </div>\n  );\n}\n\nconst MIN_PANE_W = 170;\nconst MIN_PANE_H = 132;\n\nfunction Divider({\n  windowKey,\n  splitId,\n  dir,\n}: {\n  windowKey: WindowKey;\n  splitId: string;\n  dir: \"row\" | \"col\";\n}) {\n  const ref = useRef<HTMLDivElement>(null);\n\n  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {\n    if (windowKey === \"lobby\") return;\n    const container = ref.current?.parentElement;\n    if (!container) return;\n    e.preventDefault();\n    ref.current!.setPointerCapture(e.pointerId);\n    const rect = container.getBoundingClientRect();\n\n    const onMove = (ev: globalThis.PointerEvent) => {\n      const [pos, size, min] =\n        dir === \"row\"\n          ? [ev.clientX - rect.left, rect.width, MIN_PANE_W]\n          : [ev.clientY - rect.top, rect.height, MIN_PANE_H];\n      const clamped = Math.max(min, Math.min(size - min, pos));\n      store.dispatch({\n        type: \"set-ratio\",\n        window: windowKey as WindowId,\n        splitId,\n        ratio: clamped / size,\n      });\n    };\n    const onUp = () => {\n      window.removeEventListener(\"pointermove\", onMove);\n      window.removeEventListener(\"pointerup\", onUp);\n    };\n    window.addEventListener(\"pointermove\", onMove);\n    window.addEventListener(\"pointerup\", onUp);\n  };\n\n  return (\n    <div\n      ref={ref}\n      role=\"separator\"\n      aria-orientation={dir === \"row\" ? \"vertical\" : \"horizontal\"}\n      onPointerDown={onPointerDown}\n      className={[\n        \"shrink-0 bg-border transition-colors hover:bg-accent/60\",\n        dir === \"row\" ? \"w-1.5 cursor-col-resize\" : \"h-1.5 cursor-row-resize\",\n      ].join(\" \")}\n    />\n  );\n}\n\nfunction LayoutNode({\n  windowKey,\n  node,\n  framed,\n}: {\n  windowKey: WindowKey;\n  node: PaneLayout;\n  framed: boolean;\n}) {\n  if (node.type === \"leaf\") {\n    return <PaneView windowKey={windowKey} paneId={node.paneId} framed={framed} />;\n  }\n  return (\n    <div\n      className={[\"flex min-h-0 min-w-0 flex-1\", node.dir === \"row\" ? \"flex-row\" : \"flex-col\"].join(\n        \" \",\n      )}\n    >\n      <div\n        style={{ flexBasis: `${node.ratio * 100}%` }}\n        className=\"flex min-h-0 min-w-0 shrink grow-0\"\n      >\n        <LayoutNode windowKey={windowKey} node={node.a} framed={framed} />\n      </div>\n      <Divider windowKey={windowKey} splitId={node.id} dir={node.dir} />\n      <div className=\"flex min-h-0 min-w-0 flex-1\">\n        <LayoutNode windowKey={windowKey} node={node.b} framed={framed} />\n      </div>\n    </div>\n  );\n}\n\n/** A window's pane layout: the binary split tree rendered with flexbox (§12.4). */\nexport function PaneTree({ windowKey }: { windowKey: WindowKey }) {\n  const layout = useTerminalStore((s) => getWindow(s, windowKey).layout);\n  const zoomed = useTerminalStore((s) => getWindow(s, windowKey).zoomed);\n  const paneCount = useTerminalStore((s) => getWindow(s, windowKey).panes.length);\n\n  if (zoomed) {\n    return <PaneView windowKey={windowKey} paneId={zoomed} framed />;\n  }\n  return <LayoutNode windowKey={windowKey} node={layout} framed={paneCount > 1} />;\n}\n","components/terminal/Prompt.tsx":"\"use client\";\n\nimport { useEffect, useRef } from \"react\";\nimport { PromptLabel } from \"./PromptLabel\";\nimport { activeWindowKey, getPaneById, getWindow } from \"@/lib/terminal/reducer\";\nimport { store } from \"@/lib/terminal/store\";\nimport { executeCommand } from \"@/lib/terminal/executor\";\nimport { completeLine } from \"@/lib/terminal/completion\";\nimport { useTerminalStore } from \"@/lib/terminal/useTerminalStore\";\nimport type { AppState, WindowKey } from \"@/lib/terminal/types\";\n\n/** NORMAL-mode line rendering: text with a block cursor (§6.2). */\nfunction NormalLine({ text, pos }: { text: string; pos: number }) {\n  const at = Math.min(pos, Math.max(0, text.length - 1));\n  return (\n    <span className=\"whitespace-pre font-mono text-sm text-fg\">\n      {text.slice(0, at)}\n      <span className=\"bg-[var(--accent)] text-[var(--bg-window)]\">\n        {text[at] ?? \" \"}\n      </span>\n      {text.slice(at + 1)}\n    </span>\n  );\n}\n\ninterface PromptProps {\n  windowKey: WindowKey;\n  paneId: string;\n}\n\n/**\n * One shell prompt, store-backed. INSERT editing lives on the native input\n * (soft keyboards, IME, a11y); in NORMAL the global keyboard module drives\n * the vim machine and this renders the buffer with a block cursor.\n */\nexport function Prompt({ windowKey, paneId }: PromptProps) {\n  const inputRef = useRef<HTMLInputElement>(null);\n  const pane = (s: AppState) => getPaneById(s, windowKey, paneId);\n  const value = useTerminalStore((s) => pane(s)?.inputBuffer ?? \"\");\n  const cursorPos = useTerminalStore((s) => pane(s)?.cursorPos ?? 0);\n  const mode = useTerminalStore((s) => pane(s)?.mode ?? \"INSERT\");\n  const cwd = useTerminalStore((s) => pane(s)?.cwd ?? \"~\");\n  const isActive = useTerminalStore(\n    (s) => activeWindowKey(s) === windowKey && getWindow(s, windowKey).activePane === paneId,\n  );\n\n  // The focused pane's prompt takes keyboard focus (fine pointers only —\n  // never raise the soft keyboard uninvited, §11). Re-acquire focus and the\n  // stored cursor when returning from NORMAL.\n  useEffect(() => {\n    if (isActive && mode === \"INSERT\" && window.matchMedia?.(\"(pointer: fine)\").matches) {\n      const el = inputRef.current;\n      el?.focus({ preventScroll: true });\n      el?.setSelectionRange(cursorPos, cursorPos);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [isActive, mode]);\n\n  const setInput = (text: string, pos: number) =>\n    store.dispatch({ type: \"set-input\", windowKey, text, cursorPos: pos });\n\n  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {\n    if (mode !== \"INSERT\") {\n      e.preventDefault();\n      return;\n    }\n    if (e.key === \"Escape\") {\n      // INSERT → NORMAL; the cursor steps left, like vim (§6.1).\n      e.preventDefault();\n      const sel = inputRef.current?.selectionStart ?? value.length;\n      store.dispatch({ type: \"set-cursor\", windowKey, pos: Math.max(0, sel - 1) });\n      store.dispatch({ type: \"set-mode\", windowKey, mode: \"NORMAL\" });\n      return;\n    }\n    if (e.key === \"Enter\") {\n      e.preventDefault();\n      const line = value;\n      setInput(\"\", 0);\n      executeCommand(line, { source: \"typed\" });\n      return;\n    }\n    if (e.key === \"ArrowUp\") {\n      e.preventDefault();\n      store.dispatch({ type: \"history-walk\", windowKey, direction: -1 });\n      return;\n    }\n    if (e.key === \"ArrowDown\") {\n      e.preventDefault();\n      store.dispatch({ type: \"history-walk\", windowKey, direction: 1 });\n      return;\n    }\n    if (e.key === \"Tab\") {\n      e.preventDefault();\n      const result = completeLine(value, cwd);\n      if (result.text) {\n        setInput(result.text, result.text.length);\n      } else if (result.candidates) {\n        store.dispatch({\n          type: \"append-line\",\n          windowKey,\n          command: null,\n          node: (\n            <p className=\"font-mono text-sm text-muted\">{result.candidates.join(\"  \")}</p>\n          ),\n        });\n      }\n      return;\n    }\n    if (e.key === \"c\" && e.ctrlKey) {\n      e.preventDefault();\n      setInput(\"\", 0);\n      return;\n    }\n  };\n\n  return (\n    <div className=\"flex items-center gap-2\">\n      <PromptLabel path={cwd} />\n      {mode === \"NORMAL\" ? (\n        <NormalLine text={value} pos={cursorPos} />\n      ) : (\n        <input\n          ref={inputRef}\n          type=\"text\"\n          value={value}\n          onChange={(e) => setInput(e.target.value, e.target.selectionStart ?? 0)}\n          onSelect={(e) => {\n            const pos = e.currentTarget.selectionStart ?? 0;\n            store.dispatch({ type: \"set-cursor\", windowKey, pos });\n          }}\n          onKeyDown={onKeyDown}\n          aria-label=\"Terminal command input\"\n          aria-describedby=\"input-hint\"\n          autoCapitalize=\"off\"\n          autoComplete=\"off\"\n          autoCorrect=\"off\"\n          spellCheck={false}\n          enterKeyHint=\"send\"\n          className=\"min-w-0 flex-1 border-none bg-transparent font-mono text-sm text-fg caret-[var(--accent)] outline-none\"\n        />\n      )}\n    </div>\n  );\n}\n","components/terminal/PaneScrollback.tsx":"\"use client\";\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { PromptLabel } from \"./PromptLabel\";\nimport { getPaneById } from \"@/lib/terminal/reducer\";\nimport { useTerminalStore } from \"@/lib/terminal/useTerminalStore\";\nimport type { WindowKey } from \"@/lib/terminal/types\";\n\ninterface PaneScrollbackProps {\n  windowKey: WindowKey;\n  paneId: string;\n}\n\n/**\n * A pane's scrollback. Command lines echo with the prompt as it looked when\n * they ran; output lines render their node. role=\"log\" + polite live region\n * per the accessibility non-negotiables.\n */\nexport function PaneScrollback({ windowKey, paneId }: PaneScrollbackProps) {\n  const lines = useTerminalStore(\n    (s) => getPaneById(s, windowKey, paneId)?.scrollback ?? [],\n  );\n  const containerRef = useRef<HTMLDivElement>(null);\n  const lastCommandId = useRef<number | null>(null);\n  const [unseen, setUnseen] = useState(false);\n\n  const scrollContainer = () =>\n    containerRef.current?.closest<HTMLElement>(\"[data-pane-scroll]\") ?? null;\n\n  const atBottom = () => {\n    const el = scrollContainer();\n    if (!el) return true;\n    return el.scrollTop + el.clientHeight >= el.scrollHeight - 80;\n  };\n\n  // Scroll each new command's echo to the top so its output reads from the\n  // start — but never yank the view while the reader is scrolled up (§6.3);\n  // show the new-output pill instead. System-only appends (MOTD) stay put.\n  useEffect(() => {\n    const lastCmd = [...lines].reverse().find((l) => l.command !== null);\n    if (!lastCmd || lastCmd.id === lastCommandId.current) return;\n    lastCommandId.current = lastCmd.id;\n    if (atBottom()) {\n      containerRef.current\n        ?.querySelector(`[data-entry-id=\"${lastCmd.id}\"]`)\n        ?.scrollIntoView({ block: \"start\" });\n      return;\n    }\n    const id = requestAnimationFrame(() => setUnseen(true));\n    return () => cancelAnimationFrame(id);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [lines]);\n\n  // Reaching the bottom (by any means) clears the pill.\n  useEffect(() => {\n    if (!unseen) return;\n    const el = scrollContainer();\n    if (!el) return;\n    const onScroll = () => {\n      if (atBottom()) setUnseen(false);\n    };\n    el.addEventListener(\"scroll\", onScroll);\n    return () => el.removeEventListener(\"scroll\", onScroll);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [unseen]);\n\n  const jumpToBottom = () => {\n    const el = scrollContainer();\n    if (el) el.scrollTop = el.scrollHeight;\n    setUnseen(false);\n  };\n\n  return (\n    <div ref={containerRef} role=\"log\" aria-live=\"polite\" className=\"space-y-4\">\n      {lines.map((line) =>\n        line.command !== null ? (\n          <div key={line.id} data-entry-id={line.id} className=\"scroll-mt-2\">\n            <PromptLabel path={line.cwd ?? \"~\"} />{\" \"}\n            <span className=\"font-mono text-sm text-fg\">{line.command}</span>\n          </div>\n        ) : typeof line.node === \"string\" ? (\n          <p key={line.id} data-entry-id={line.id} className=\"font-mono text-xs text-muted\">\n            {line.node}\n          </p>\n        ) : (\n          <div key={line.id} data-entry-id={line.id} className=\"output-fade\">\n            {line.node}\n          </div>\n        ),\n      )}\n      {unseen && (\n        <div className=\"sticky bottom-2 z-10 flex justify-center\">\n          <button\n            type=\"button\"\n            onClick={jumpToBottom}\n            className=\"cursor-pointer rounded-full border border-accent/50 bg-elevated px-3 py-1 font-mono text-xs text-accent shadow hover:bg-accent/10\"\n          >\n            ↓ new output\n          </button>\n        </div>\n      )}\n    </div>\n  );\n}\n","data/projects.ts":"/**\n * Projects. Each project is a directory under ~/projects in the virtual\n * filesystem (FLOW.md §2): a README.md plus, optionally, real source files\n * under src/. Cards in the server-rendered fallback read the same data.\n */\nexport interface ProjectCommit {\n  hash: string; // short hash, e.g. \"3f2a91c\"\n  date: string; // \"2026-05-12\"\n  message: string;\n}\n\nexport interface Project {\n  slug: string;\n  title: string;\n  pitch: string; // one line: what it is and why it matters\n  description?: string; // optional longer blurb shown on expand\n  stack: string[]; // tags, colored via --ansi-* tokens\n  liveUrl?: string; // shows a \"Live\" badge + link\n  sourceUrl?: string; // shows a \"Source\" link\n  thumbnail?: string; // /public path, optional\n  featured?: boolean;\n  /** Markdown README; omitted → generated from the fields above. */\n  readme?: string;\n  /** Abbreviated commit history shown by `git log` inside the project dir. */\n  commits?: ProjectCommit[];\n}\n\nexport const projects: Project[] = [\n  {\n    slug: \"terminal-portfolio\",\n    title: \"TODO Terminal Portfolio\",\n    pitch: \"TODO One line on what it does for a user, then why it matters.\",\n    description:\n      \"TODO An optional longer blurb. Describe the problem it solves and one thing you're proud of in the build.\",\n    stack: [\"Next.js\", \"TypeScript\", \"Tailwind\"],\n    liveUrl: \"https://example.com\",\n    sourceUrl: \"https://github.com/yourname/project\",\n    featured: true,\n  },\n  {\n    slug: \"second-project\",\n    title: \"TODO Second Project\",\n    pitch: \"TODO What it is and the value it delivers, in one specific line.\",\n    stack: [\"Python\", \"Postgres\"],\n    sourceUrl: \"https://github.com/yourname/second-project\",\n    featured: true,\n  },\n  {\n    slug: \"third-project\",\n    title: \"TODO Third Project\",\n    pitch: \"TODO Specific beats clever — say what it actually does.\",\n    stack: [\"Go\", \"Docker\"],\n    liveUrl: \"https://example.com\",\n  },\n];\n"}};

